import React, { useEffect, useMemo, useState } from "react";
import {
  Extension,
  INTERNAL_SYSTEM_SLOT,
  extension,
  settings,
  useExtensionContext,
  type ExtensionContext,
  type ExtensionProps,
  type SettingsBuilder,
} from "@avg-studio/sdk";
import type { ArchiveSlot } from "@avg-studio/sdk";
import { tokens } from "./shared-tokens";
import {
  useScreenTransition,
  useOverlayStyles,
  useEnterStyles,
  type ScreenPhase,
} from "./use-screen-transition";
import { usePressable } from "./use-pressable";
import { ScreenHeader, CloseButton } from "./screen-chrome";
import { showToast } from "./toast";

const PAGE_SIZE = 6;

/**
 * 画面工作模式 —— 由 ctx.system.invoke(Save | Load) 通过 payload 透传。
 * "save": 优先体现"保存到/覆盖到某槽位"
 * "load": 优先体现"读取某槽位",空槽位禁用,不允许"覆盖"减少误操作
 */
type SaveScreenMode = "save" | "load";
type SaveScreenSource = "title" | "game";

const VISUAL_SAVE_SCREEN = "@avg.internal.default-shell/save-screen";

interface SaveScreenProps extends ExtensionProps {
  mode?: SaveScreenMode;
  source?: SaveScreenSource;
}

/**
 * 存档画面 —— 大气版 + 全元素 stagger 入场。
 *
 * 入场:
 *   - overlay backdrop blur 0→24
 *   - header 滑入
 *   - 翻页箭头淡入
 *   - 卡片 grid 用 avg-card-rise(blur+lift+scale),逐张 stagger
 *   - 底部页码 dots 上浮
 *
 * 卡片:大气浮起 hover + press 反馈,整张卡即主操作入口
 *
 * mode 行为:
 *   - save 模式: 空槽位点击即保存,已有槽位点击后确认覆盖
 *   - load 模式: 标题画面点击即读取,游戏中点击后确认读取
 *
 *   删除按钮在非空槽位 hover 时显示为右上角红叉,受 allowDelete 设置控制,
 *   避免玩家在读档画面无法清理废弃存档。
 *
 * 危险操作前的确认:覆盖已有存档、读取存档(放弃当前进度)、删除存档,
 * 全部用 inline 双确认弹层防误操作。
 */

const SaveScreenComponent: React.FC<SaveScreenProps> = ({ mode = "save", source = "game" }) => {
  const ctx = useExtensionContext();

  const slots = ctx.archive.useSlots();
  // ctx 已 scope 到 (extId, "save-screen"),get 自动加 "save-screen." 前缀
  const slotCount = ctx.settings.get<number>("slotCount") ?? 30;
  const allowDelete = ctx.settings.get<boolean>("allowDelete") ?? true;

  const { phase, requestClose } = useScreenTransition(ctx, "save-screen");

  // 危险操作的二次确认。一次只能有一个 pending(覆盖/读取/删除),
  // 弹层居中显示,Esc / 右键 / 点遮罩取消。
  const [pendingConfirm, setPendingConfirm] = useState<{
    slotId: number;
    action: "save" | "load" | "delete";
  } | null>(null);

  const [page, setPage] = useState(0);
  const [pageDir, setPageDir] = useState<"right" | "left">("right");

  const totalPages = Math.max(1, Math.ceil(slotCount / PAGE_SIZE));

  const displaySlots = useMemo(() => {
    const start = page * PAGE_SIZE;
    const items: Array<{ id: number; slot: ArchiveSlot | null }> = [];
    for (let i = 0; i < PAGE_SIZE; i++) {
      const id = start + i + 1;
      if (id > slotCount) break;
      const found = slots.find((s) => s.id === id) ?? null;
      items.push({ id, slot: found });
    }
    return items;
  }, [page, slots, slotCount]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        // ESC 优先取消 confirm,否则关画面
        if (pendingConfirm) setPendingConfirm(null);
        else requestClose();
        return;
      }
      // 翻页快捷键:confirm 弹出时屏蔽,避免误翻
      if (pendingConfirm) return;
      if (e.key === "ArrowLeft") goPrev();
      if (e.key === "ArrowRight") goNext();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page, totalPages, pendingConfirm]);

  const goPrev = () => {
    if (page > 0) {
      setPageDir("left");
      setPage((p) => p - 1);
    }
  };
  const goNext = () => {
    if (page < totalPages - 1) {
      setPageDir("right");
      setPage((p) => p + 1);
    }
  };

  // 真正执行 archive 操作,确认后才调。
  // load 会就地重跑引擎(清场 + seek 到 cursorIndex),所有 UI 容器被关闭,
  // 不需要显式 requestClose —— 但提前调一下让退出动画自然一些。
  const doSave = (id: number) => {
    ctx.archive
      .save(id)
      .then(() => showToast(`已保存到 #${String(id).padStart(2, "0")}`, { type: "success" }))
      .catch((err) => {
        console.error("[save-screen] save failed", err);
        showToast("保存失败", { type: "error" });
      });
  };
  const doLoad = (id: number) => {
    void ctx.archive.load(id);
    requestClose();
  };
  const doDelete = (id: number) => {
    ctx.archive
      .delete(id)
      .then(() => showToast(`已删除 #${String(id).padStart(2, "0")}`, { type: "info" }))
      .catch((err) => {
        console.error("[save-screen] delete failed", err);
        showToast("删除失败", { type: "error" });
      });
  };

  // 卡片按钮点击的入口 —— 按"是否需要确认"分发到 do* 或 pendingConfirm
  const onSaveClick = (id: number, isEmpty: boolean) => {
    if (isEmpty) {
      // 空槽位保存 = 没风险,直接写
      doSave(id);
      return;
    }
    // 覆盖已有存档要二次确认
    setPendingConfirm({ slotId: id, action: "save" });
  };
  const onLoadClick = (id: number) => {
    if (source === "title") {
      doLoad(id);
      return;
    }
    setPendingConfirm({ slotId: id, action: "load" });
  };
  const onDeleteClick = (id: number) => {
    // 删除不可逆,二次确认
    setPendingConfirm({ slotId: id, action: "delete" });
  };
  const onConfirm = () => {
    if (!pendingConfirm) return;
    const { slotId, action } = pendingConfirm;
    setPendingConfirm(null);
    if (action === "save") doSave(slotId);
    else if (action === "load") doLoad(slotId);
    else if (action === "delete") doDelete(slotId);
  };
  const onCancelConfirm = () => setPendingConfirm(null);

  const overlayStyles = useOverlayStyles(phase);
  const footerStyles = useEnterStyles({
    hidden: { opacity: 0, transform: "translateY(14px)" },
    delay: 280,
  });

  // 右键关闭 / 取消 confirm
  const onContextMenu = (e: React.MouseEvent) => {
    e.preventDefault();
    // 优先取消正在显示的 confirm,否则关闭整个画面
    if (pendingConfirm) {
      setPendingConfirm(null);
    } else {
      requestClose();
    }
  };

  return (
    <div
      onContextMenu={onContextMenu}
      style={{
        position: "absolute",
        inset: 0,
        background: tokens.bgOverlay,
        backdropFilter: "blur(24px)",
        WebkitBackdropFilter: "blur(24px)",
        color: tokens.textPrimary,
        fontFamily: tokens.fontUI,
        display: "flex",
        flexDirection: "column",
        willChange: "opacity",
        ...overlayStyles,
      }}
    >
      <ScreenHeader
        eyebrow={mode === "load" ? "Load" : "Save"}
        title={mode === "load" ? "读取存档" : "保存存档"}
        phase={phase}
        rightSlot={
          <>
            <span
              style={{
                fontFamily: tokens.fontMono,
                fontSize: 14,
                color: tokens.textMuted,
                fontWeight: 600,
                fontVariantNumeric: "tabular-nums",
                marginRight: 4,
              }}
            >
              {String(page + 1).padStart(2, "0")} /{" "}
              {String(totalPages).padStart(2, "0")}
            </span>
            <CloseButton onClick={requestClose} />
          </>
        }
      />

      {/* 主区:箭头 + grid */}
      <div
        style={{
          flex: 1,
          display: "grid",
          gridTemplateColumns: "88px 1fr 88px",
          gap: 16,
          padding: "0 56px 24px",
          minHeight: 0,
          alignItems: "center",
        }}
      >
        <ArrowButton
          dir="left"
          disabled={page === 0}
          onClick={goPrev}
          delay={160}
          phase={phase}
        />

        <div
          // page 变化时强制重建子树触发新 stagger
          key={page}
          style={{
            display: "grid",
            gridTemplateColumns: "repeat(3, 1fr)",
            gridTemplateRows: "repeat(2, 1fr)",
            gap: 24,
            height: "100%",
            animation: `${
              pageDir === "right"
                ? "avg-page-slide-in-right"
                : "avg-page-slide-in-left"
            } ${tokens.durBase}ms ${tokens.easeOut}`,
          }}
        >
          {displaySlots.map(({ id, slot }, idx) => {
            return (
            <SlotCard
              key={id}
              id={id}
              slot={slot}
              snapshotUrl={slot?.snapshotDataUri ?? null}
              allowDelete={allowDelete}
              mode={mode}
              onSave={() => onSaveClick(id, slot === null)}
              onLoad={() => onLoadClick(id)}
              onDelete={() => onDeleteClick(id)}
              animationDelay={120 + idx * 40}
              phase={phase}
            />
            );
          })}
        </div>

        <ArrowButton
          dir="right"
          disabled={page >= totalPages - 1}
          onClick={goNext}
          delay={160}
          phase={phase}
        />
      </div>

      {/* 页码 dots */}
      <footer
        style={{
          padding: "16px 0 40px",
          display: "flex",
          justifyContent: "center",
          gap: 10,
          ...footerStyles,
        }}
      >
        {Array.from({ length: totalPages }).map((_, i) => (
          <PageDot
            key={i}
            active={i === page}
            onClick={() => {
              setPageDir(i > page ? "right" : "left");
              setPage(i);
            }}
            label={`第 ${i + 1} 页`}
          />
        ))}
      </footer>

      {pendingConfirm && (
        <ConfirmOverlay
          action={pendingConfirm.action}
          slotId={pendingConfirm.slotId}
          onConfirm={onConfirm}
          onCancel={onCancelConfirm}
        />
      )}
    </div>
  );
};

// ---------- PageDot ----------

const PageDot: React.FC<{
  active: boolean;
  onClick: () => void;
  label: string;
}> = ({ active, onClick, label }) => {
  const press = usePressable();
  return (
    <button
      {...press.handlers}
      onClick={onClick}
      aria-label={label}
      style={{
        appearance: "none",
        width: active ? 32 : 8,
        height: 8,
        borderRadius: 999,
        border: "none",
        padding: 0,
        background: active ? tokens.accent : tokens.borderRegular,
        cursor: "default",
        boxShadow: active ? `0 0 12px ${tokens.accentGlow}` : "none",
        transform: press.pressed ? "scale(0.85)" : "scale(1)",
        transition: `width ${tokens.durBase}ms ${tokens.easeOut}, background ${tokens.durBase}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}, box-shadow ${tokens.durBase}ms ${tokens.easeOut}`,
      }}
    />
  );
};

// ---------- SlotCard ----------

const SlotCard: React.FC<{
  id: number;
  slot: ArchiveSlot | null;
  snapshotUrl: string | null;
  allowDelete: boolean;
  mode: SaveScreenMode;
  onSave: () => void;
  onLoad: () => void;
  onDelete: () => void;
  animationDelay: number;
  phase: ScreenPhase;
}> = ({
  id,
  slot,
  snapshotUrl,
  allowDelete,
  mode,
  onSave,
  onLoad,
  onDelete,
  animationDelay,
  phase,
}) => {
  const [hover, setHover] = useState(false);
  const [deleteHover, setDeleteHover] = useState(false);
  const press = usePressable();
  const isEmpty = slot === null;
  // load 模式下空槽位整张卡禁用 — 没有可读的存档
  const disabledInLoadMode = mode === "load" && isEmpty;
  const isInteractive = !disabledInLoadMode;
  const slotNumber = String(id).padStart(2, "0");
  const cardLabel = isEmpty
    ? mode === "save"
      ? `保存到空槽位 #${slotNumber}`
      : `空槽位 #${slotNumber}`
    : mode === "save"
      ? `覆盖存档 #${slotNumber}`
      : `读取存档 #${slotNumber}`;

  const onPrimaryAction = () => {
    if (!isInteractive) return;
    if (mode === "save") onSave();
    else onLoad();
  };

  const fallbackBg = useMemo(() => {
    // 空槽位的卡片底色 —— 之前用 oklch(0.32 0.06 H),但 html2canvas 1.4
    // 不支持 oklch,SaveScreen 在屏时点保存会让截图整体崩溃。改用 hsl 等价值。
    // hsl(H, 12%, 22%) ≈ oklch(0.32 0.06 H);hsl(H+50, 10%, 16%) ≈ oklch(0.22 0.04 ...)
    const hue = (id * 37) % 360;
    return `linear-gradient(135deg,
      hsl(${hue}, 12%, 22%) 0%,
      hsl(${(hue + 50) % 360}, 10%, 16%) 100%)`;
  }, [id]);

  // 入场动画:外层 wrapper 用 inline style hook,内层 article 自带 hover/press transition
  // 2026-05:去掉 filter: blur(4px) —— blur 滤镜在 macOS 上极度耗 GPU,
  // 6 张卡片同步 blur→clear 是"重、迟钝"的主要来源。translateY+scale 已足够"浮起"感。
  const wrapperStyles = useEnterStyles({
    hidden: {
      opacity: 0,
      transform: "translateY(18px) scale(0.97)",
    },
    delay: animationDelay,
    duration: tokens.durSlow,
  });

  return (
    <div
      style={{ display: "flex", ...wrapperStyles }}
    >
    <article
      onMouseEnter={() => {
        if (isInteractive) setHover(true);
      }}
      onMouseLeave={(e) => {
        setHover(false);
        setDeleteHover(false);
        press.handlers.onPointerLeave(e as unknown as React.PointerEvent);
      }}
      onPointerDown={(e) => {
        if (!isInteractive) return;
        // press.handlers.onPointerDown 实际不需要参数,旧代码统一传 e,
        // 这里跟其它调用点保持一致(项目历史 TS 警告,不在本次范围)。
        press.handlers.onPointerDown(e as unknown as never);
      }}
      style={{
        flex: 1,
        position: "relative",
        background: tokens.bgSurface,
        border: `1.5px solid ${
          hover && isInteractive ? tokens.borderAccent : tokens.borderSubtle
        }`,
        borderRadius: tokens.radiusLg,
        overflow: "hidden",
        display: "flex",
        flexDirection: "column",
        transform: press.pressed
          ? "translateY(-2px) scale(0.98)"
          : hover && isInteractive
            ? "translateY(-6px) scale(1.01)"
            : "translateY(0) scale(1)",
        boxShadow:
          hover && isInteractive
            ? "0 28px 56px rgba(0,0,0,0.55), 0 0 0 1px rgba(212,165,116,0.22), 0 0 32px rgba(212,165,116,0.10)"
            : "0 4px 16px rgba(0,0,0,0.25)",
        transition: `transform ${tokens.durFast}ms ${tokens.easeOut}, border-color ${tokens.durFast}ms ${tokens.easeOut}, box-shadow ${tokens.durBase}ms ${tokens.easeOut}`,
        cursor: isInteractive ? "default" : "not-allowed",
        // load 模式空槽位:整张卡灰化 + 不响应
        opacity: disabledInLoadMode ? 0.45 : 1,
      }}
    >
      <button
        type="button"
        aria-label={cardLabel}
        disabled={!isInteractive}
        onClick={onPrimaryAction}
        style={{
          position: "absolute",
          inset: 0,
          zIndex: 1,
          appearance: "none",
          border: "none",
          padding: 0,
          background: "transparent",
          color: "transparent",
          cursor: isInteractive ? "default" : "not-allowed",
        }}
      />
      {/* 截图区
          2026-05:之前用 background:url(...) center/cover 渲染快照,浏览器
          会按原始分辨率 decode + 缩放,旧存档(未压缩 PNG)在 6 卡同时渲染
          时主线程被吃满,翻页/打开都卡。
          改成独立 <img decoding="async" loading="lazy"> + object-fit:cover,
          decode 在后台线程跑,且不立即占主线程。fallback 渐变保留在父层,
          快照加载前/失败也有底色。 */}
      <div
        style={{
          position: "relative",
          flex: "1 1 0",
          minHeight: 0,
          background: fallbackBg,
          overflow: "hidden",
        }}
      >
        {snapshotUrl && (
          <img
            src={snapshotUrl}
            alt=""
            decoding="async"
            loading="lazy"
            draggable={false}
            style={{
              position: "absolute",
              inset: 0,
              width: "100%",
              height: "100%",
              objectFit: "cover",
              pointerEvents: "none",
              userSelect: "none",
            }}
          />
        )}
        {/* 槽位号 */}
        <div
          style={{
            position: "absolute",
            top: 14,
            left: 16,
            fontFamily: tokens.fontMono,
            fontSize: 13,
            letterSpacing: "0.24em",
            color: tokens.textPrimary,
            textShadow: "0 1px 6px rgba(0,0,0,0.9)",
            background: "rgba(0,0,0,0.45)",
            padding: "5px 11px",
            borderRadius: 6,
            backdropFilter: "blur(8px)",
            WebkitBackdropFilter: "blur(8px)",
            fontWeight: 600,
          }}
        >
          #{String(id).padStart(2, "0")}
        </div>

        {slot?.isQuickSave && (
          <div
            style={{
              position: "absolute",
              top: 14,
              right: 16,
              fontFamily: tokens.fontMono,
              fontSize: 11,
              letterSpacing: "0.24em",
              color: tokens.accent,
              background: "rgba(0,0,0,0.45)",
              padding: "5px 11px",
              borderRadius: 6,
              backdropFilter: "blur(8px)",
              WebkitBackdropFilter: "blur(8px)",
              fontWeight: 700,
            }}
          >
            QUICK
          </div>
        )}

        {!isEmpty && allowDelete && (
          <button
            type="button"
            aria-label={`删除存档 #${slotNumber}`}
            aria-hidden={!hover}
            tabIndex={hover ? 0 : -1}
            onClick={(e) => {
              e.stopPropagation();
              onDelete();
            }}
            onPointerDown={(e) => e.stopPropagation()}
            onMouseEnter={(e) => {
              e.stopPropagation();
              setDeleteHover(true);
            }}
            onMouseLeave={(e) => {
              e.stopPropagation();
              setDeleteHover(false);
            }}
            onFocus={() => {
              setHover(true);
              setDeleteHover(true);
            }}
            onBlur={() => {
              setHover(false);
              setDeleteHover(false);
            }}
            style={{
              position: "absolute",
              top: 14,
              right: slot?.isQuickSave ? 98 : 16,
              zIndex: 3,
              width: 42,
              height: 42,
              borderRadius: "50%",
              border: `1.5px solid ${
                deleteHover ? "rgba(255,154,146,0.96)" : "rgba(255,126,116,0.82)"
              }`,
              background: deleteHover
                ? "rgba(255,232,230,0.96)"
                : "rgba(255,246,245,0.88)",
              color: tokens.danger,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              opacity: hover ? 1 : 0,
              visibility: hover ? "visible" : "hidden",
              transform: hover
                ? `translateY(0) scale(${deleteHover ? 1.1 : 1}) rotate(${deleteHover ? 4 : 0}deg)`
                : "translateY(-4px) scale(0.92) rotate(0deg)",
              pointerEvents: hover ? "auto" : "none",
              boxShadow:
                deleteHover
                  ? "0 16px 34px rgba(0,0,0,0.38), 0 0 0 2px rgba(224,99,90,0.22), 0 0 30px rgba(224,99,90,0.38)"
                  : "0 12px 26px rgba(0,0,0,0.30), 0 0 0 2px rgba(255,255,255,0.30), 0 0 22px rgba(224,99,90,0.22)",
              backdropFilter: "blur(10px)",
              WebkitBackdropFilter: "blur(10px)",
              transition: `opacity ${tokens.durFast}ms ${tokens.easeOut}, visibility ${tokens.durFast}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}, background ${tokens.durFast}ms ${tokens.easeOut}, box-shadow ${tokens.durFast}ms ${tokens.easeOut}`,
              cursor: "default",
            }}
          >
            <svg width="20" height="20" viewBox="0 0 20 20" aria-hidden="true">
              <path
                d="M5 5l10 10M15 5 5 15"
                fill="none"
                stroke="rgba(255,255,255,0.98)"
                strokeWidth="4.8"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
              <path
                d="M5 5l10 10M15 5 5 15"
                fill="none"
                stroke="currentColor"
                strokeWidth="2.6"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        )}

        {isEmpty && (
          <div
            style={{
              position: "absolute",
              inset: 0,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              color: tokens.textFaint,
              fontFamily: tokens.fontDisplay,
              fontSize: 24,
              fontWeight: 500,
              letterSpacing: "0.08em",
            }}
          >
            EMPTY
          </div>
        )}
      </div>

      {/* 文本/时间 */}
      <div
        style={{
          padding: "14px 18px 16px",
          background: tokens.bgSunken,
          borderTop: `1px solid ${tokens.borderSubtle}`,
          minHeight: 72,
        }}
      >
        {slot ? (
          <>
            {slot.currentSpeaker && (
              <div
                style={{
                  fontFamily: tokens.fontUI,
                  fontSize: 13,
                  fontWeight: 700,
                  letterSpacing: "0.04em",
                  color: tokens.accent,
                  marginBottom: 6,
                }}
              >
                {slot.currentSpeaker}
              </div>
            )}
            <div
              style={{
                fontSize: 14,
                lineHeight: 1.55,
                color: tokens.textPrimary,
                display: "-webkit-box",
                WebkitLineClamp: 2,
                WebkitBoxOrient: "vertical",
                overflow: "hidden",
                textWrap: "pretty",
                fontWeight: 400,
              }}
            >
              {slot.currentDialogueText || "—"}
            </div>
            <div
              style={{
                marginTop: 8,
                fontFamily: tokens.fontMono,
                fontSize: 11,
                letterSpacing: "0.06em",
                color: tokens.textFaint,
                fontWeight: 500,
              }}
            >
              {formatTime(slot.modifiedTime)}
            </div>
          </>
        ) : (
          <div
            style={{
              fontFamily: tokens.fontMono,
              fontSize: 12,
              letterSpacing: "0.20em",
              color: tokens.textFaint,
              textTransform: "uppercase",
              fontWeight: 600,
            }}
          >
            no data
          </div>
        )}
      </div>
    </article>
    </div>
  );
};

// ---------- CardActionButton ----------

const CardActionButton: React.FC<{
  onClick: () => void;
  children: React.ReactNode;
  primary?: boolean;
  danger?: boolean;
}> = ({ onClick, children, primary, danger }) => {
  const [hover, setHover] = useState(false);
  const press = usePressable();

  const bg = primary
    ? hover
      ? tokens.accent
      : "rgba(212,165,116,0.92)"
    : danger
      ? hover
        ? tokens.danger
        : tokens.dangerSoft
      : hover
        ? tokens.bgElevated
        : "rgba(255,255,255,0.10)";

  const color = primary
    ? tokens.textOnAccent
    : danger
      ? hover
        ? "#fff"
        : tokens.danger
      : tokens.textPrimary;

  return (
    <button
      onClick={(e) => {
        e.stopPropagation();
        onClick();
      }}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={(e) => {
        setHover(false);
        press.handlers.onPointerLeave(e as unknown as React.PointerEvent);
      }}
      onPointerDown={press.handlers.onPointerDown}
      style={{
        appearance: "none",
        border: `1px solid ${
          primary
            ? "transparent"
            : danger
              ? "rgba(224,99,90,0.45)"
              : tokens.borderRegular
        }`,
        background: bg,
        color,
        fontFamily: tokens.fontUI,
        fontSize: 13,
        fontWeight: 600,
        letterSpacing: "0.06em",
        padding: "10px 18px",
        borderRadius: tokens.radiusSm,
        cursor: "default",
        backdropFilter: "blur(10px)",
        WebkitBackdropFilter: "blur(10px)",
        boxShadow: primary
          ? hover
            ? `0 6px 20px ${tokens.accentGlow}`
            : "0 2px 8px rgba(0,0,0,0.3)"
          : "0 2px 8px rgba(0,0,0,0.3)",
        transform: press.pressed
          ? "scale(0.94)"
          : hover
            ? "translateY(-2px) scale(1.04)"
            : "scale(1)",
        transition: `background ${tokens.durFast}ms ${tokens.easeOut}, color ${tokens.durFast}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}, box-shadow ${tokens.durBase}ms ${tokens.easeOut}`,
      }}
    >
      {children}
    </button>
  );
};

// ---------- ConfirmOverlay ----------

const ConfirmOverlay: React.FC<{
  action: "save" | "load" | "delete";
  slotId: number;
  onConfirm: () => void;
  onCancel: () => void;
}> = ({ action, slotId, onConfirm, onCancel }) => {
  const enterStyles = useEnterStyles({
    hidden: { opacity: 0, transform: "scale(0.96)" },
    duration: tokens.durFast,
  });
  const conf = CONFIRM_CONF[action];
  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-label={conf.title}
      onClick={onCancel}
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "rgba(0,0,0,0.42)",
        backdropFilter: "blur(8px)",
        WebkitBackdropFilter: "blur(8px)",
        zIndex: 20,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: 360,
          maxWidth: "calc(100% - 48px)",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: 16,
          padding: "26px 28px 24px",
          background: "rgba(18,20,24,0.92)",
          border: `1px solid ${conf.danger ? "rgba(224,99,90,0.52)" : tokens.borderAccent}`,
          borderRadius: tokens.radiusLg,
          boxShadow: conf.danger
            ? "0 28px 72px rgba(0,0,0,0.62), 0 0 36px rgba(224,99,90,0.16)"
            : `0 28px 72px rgba(0,0,0,0.62), 0 0 36px ${tokens.accentGlow}`,
          ...enterStyles,
        }}
      >
        <div
          style={{
            fontFamily: tokens.fontMono,
            fontSize: 12,
            letterSpacing: "0.20em",
            color: conf.danger ? tokens.danger : tokens.accent,
            textTransform: "uppercase",
            fontWeight: 700,
          }}
        >
          #{String(slotId).padStart(2, "0")}
        </div>
        <div
          style={{
            fontFamily: tokens.fontDisplay,
            fontSize: 22,
            fontWeight: 600,
            color: tokens.textPrimary,
            textAlign: "center",
          }}
        >
          {conf.title}
        </div>
        <div
          style={{
            fontFamily: tokens.fontUI,
            fontSize: 14,
            fontWeight: 500,
            color: tokens.textSecondary,
            textAlign: "center",
            lineHeight: 1.6,
          }}
        >
          {conf.message}
        </div>
        <div style={{ display: "flex", gap: 10, marginTop: 2 }}>
          <CardActionButton onClick={onConfirm} primary={!conf.danger} danger={conf.danger}>
            {conf.confirmLabel}
          </CardActionButton>
          <CardActionButton onClick={onCancel}>取消</CardActionButton>
        </div>
      </div>
    </div>
  );
};

const CONFIRM_CONF: Record<
  "save" | "load" | "delete",
  { title: string; message: string; confirmLabel: string; danger?: boolean }
> = {
  save: { title: "确认覆盖存档", message: "覆盖此存档？", confirmLabel: "覆盖" },
  load: { title: "确认读取存档", message: "读取此存档？未保存的内容会丢失。", confirmLabel: "读取" },
  delete: { title: "确认删除存档", message: "删除此存档？此操作不可撤销。", confirmLabel: "删除", danger: true },
};

// ---------- ArrowButton ----------

const ArrowButton: React.FC<{
  dir: "left" | "right";
  disabled: boolean;
  onClick: () => void;
  delay: number;
  phase: ScreenPhase;
}> = ({ dir, disabled, onClick, delay }) => {
  const [hover, setHover] = useState(false);
  const press = usePressable();
  const wrapperStyles = useEnterStyles({
    hidden: { opacity: 0, transform: "translateY(14px)" },
    delay,
  });
  return (
    <div
      style={{ display: "flex", ...wrapperStyles }}
    >
    <button
      onClick={onClick}
      disabled={disabled}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={(e) => {
        setHover(false);
        press.handlers.onPointerLeave(e as unknown as React.PointerEvent);
      }}
      onPointerDown={press.handlers.onPointerDown}
      aria-label={dir === "left" ? "上一页" : "下一页"}
      style={{
        appearance: "none",
        background: hover && !disabled ? tokens.accentSoft : "transparent",
        border: `1.5px solid ${
          hover && !disabled ? tokens.borderAccent : tokens.borderSubtle
        }`,
        borderRadius: "50%",
        width: 64,
        height: 64,
        color: disabled ? tokens.textFaint : tokens.textPrimary,
        cursor: disabled ? "not-allowed" : "default",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        opacity: disabled ? 0.25 : 1,
        boxShadow:
          hover && !disabled
            ? `0 8px 24px rgba(0,0,0,0.4), 0 0 24px ${tokens.accentGlow}`
            : "0 2px 8px rgba(0,0,0,0.2)",
        transform: press.pressed
          ? "scale(0.92)"
          : hover && !disabled
            ? dir === "left"
              ? "translateX(-6px) scale(1.05)"
              : "translateX(6px) scale(1.05)"
            : "translateX(0) scale(1)",
        transition: `border-color ${tokens.durFast}ms ${tokens.easeOut}, opacity ${tokens.durFast}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}, background ${tokens.durFast}ms ${tokens.easeOut}, box-shadow ${tokens.durBase}ms ${tokens.easeOut}`,
      }}
    >
      <svg width="20" height="20" viewBox="0 0 20 20" aria-hidden>
        {dir === "left" ? (
          <path
            d="M13 3L6 10l7 7"
            stroke="currentColor"
            strokeWidth="2"
            fill="none"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        ) : (
          <path
            d="M7 3l7 7-7 7"
            stroke="currentColor"
            strokeWidth="2"
            fill="none"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        )}
      </svg>
    </button>
    </div>
  );
};

function formatTime(ts: number): string {
  const d = new Date(ts);
  const diffMin = (Date.now() - ts) / 60000;
  if (diffMin < 1) return "刚刚";
  if (diffMin < 60) return `${Math.floor(diffMin)} 分钟前`;
  if (diffMin < 60 * 24) return `${Math.floor(diffMin / 60)} 小时前`;
  return d.toLocaleString("zh-CN", {
    year: "2-digit",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

@extension({
  id: "save-screen",
  label: "存档画面",
  exposeUI: false, // 保留快存/快读和截图控制器,React 版不再进入 UI 列表
  autonomous: true, // F5/F9 全局键由 onRegister 绑定
  /**
   * 2026-05 Internal Extension Points §11.2:SaveScreen 同时支持 save / load 两个 slot,
   * 通过 mode payload 区分(由 ctx.system.invoke 透传)。
   *
   * 2026-05-19 实装:ctx.system.invoke(Save) → payload 默认填 { mode: "save" };
   * ctx.system.invoke(Load) → 调用方应该传 { mode: "load" }。
   * 兼容:payload 为空时按 "save" 模式渲染(toolbar 现有调用没传 payload)。
   */
  supportsSlot: [INTERNAL_SYSTEM_SLOT.Save, INTERNAL_SYSTEM_SLOT.Load],
})
export class SaveScreen extends Extension<SaveScreenProps> {
  // 2026-05 Internal Extension Points:删除 slotUI 字段,改由项目级
  // systemBindings 控制(在 Studio 项目设置 → 系统 面板配置)。
  static settings = settings((s: SettingsBuilder) => ({
    slotCount: s.number("槽位数量").default(30).range(1, 200),
    allowDelete: s.boolean("允许删除存档").default(true),
    // 注:F5 / F9 快捷键由 ctx.input.registerAction (走 KeyBindingSystem) 注册,
    // 玩家在个性化 → 输入按键 tab 改键。
  }));

  /**
   * 注册快存/快读语义动作,然后订阅触发。键位由 KeyBindingSystem 管理:
   *   - default_keys: F5 / F9 (跟之前 settings 默认一致)
   *   - 玩家在"输入按键"tab 改键 → 自动生效,不需要 settings.subscribe
   *   - 跨存档持久化(走 GAME_SETTINGS_TABLE.userKeyBindings)
   */
  static onRegister(ctx: ExtensionContext): void {
    // 可视化版没有 React Extension 实例的 onInit 生命周期。必须在宿主把
    // 界面挂上屏之前完成截图，否则点击槽位时会截到存档界面自身。
    ctx.visualUI.onBeforeOpen(VISUAL_SAVE_SCREEN, async () => {
      await ctx.archive.cacheGameSnapshot();
    });
    ctx.visualUI.onOpen(VISUAL_SAVE_SCREEN, (view) => {
      view.onClose(() => ctx.archive.clearGameSnapshot());
    });

    // 2026-05 Internal Extension Points §4.5:扩展贡献的 action id 必须以
    // 扩展自身 id (avg.internal.default-shell) 为前缀,由 scope-extension-context
    // 里的 assertValidExtensionActionId 强制校验。
    ctx.input.registerAction({
      id: "avg.internal.default-shell.quick-save",
      label: "快速存档",
      defaultKeys: ["F5"]
    });
    ctx.input.registerAction({
      id: "avg.internal.default-shell.quick-load",
      label: "快速读档",
      defaultKeys: ["F9"]
    });
    ctx.input.onAction("avg.internal.default-shell.quick-save", () => {
      ctx.archive
        .quickSave()
        .then(() => showToast("已快速存档 (F5)", { type: "success" }))
        .catch((err) => {
          console.error("[save-screen] quickSave failed", err);
          showToast("快速存档失败", { type: "error" });
        });
    });
    ctx.input.onAction("avg.internal.default-shell.quick-load", async () => {
      try {
        const loaded = await ctx.archive.quickLoad();
        if (!loaded) {
          showToast("没有可读取的快速存档 (F5 创建)", { type: "warn" });
        }
      } catch (err) {
        console.error("[save-screen] quickLoad failed", err);
        showToast("快速读档失败", { type: "error" });
      }
    });
  }

  /**
   * onInit 在 React 把 SaveScreen 渲染进 DOM **之前**触发。
   * 此时画面上还没有 SaveScreen 自身覆盖,触发引擎截图正好拿到"打开存档画面
   * 之前"的纯游戏画面。缓存到 ArchiveSystem,后续点保存复用,完全不闪。
   *
   * 见 archive-system.ts cachedGameSnapshot 字段说明。
   */
  onInit() {
    void this.context.archive.cacheGameSnapshot();
  }

  /** onClose 清缓存,避免下次打开 SaveScreen 时还用着上次的旧画面。 */
  onClose() {
    this.context.archive.clearGameSnapshot();
  }

  render() {
    // 把 ctor 收到的 payload 透给 React component。payload 缺失或形态非预期时,
    // mode 取 undefined → component 默认按 "save" 渲染。
    const data = this.data;
    const mode: SaveScreenMode | undefined =
      data?.mode === "save" || data?.mode === "load" ? data.mode : undefined;
    const source: SaveScreenSource | undefined =
      data?.source === "title" || data?.source === "game" ? data.source : undefined;
    return {
      component: SaveScreenComponent,
      props: { mode, source } as SaveScreenProps,
    };
  }
}
