import React, { useState } from "react";
import { tokens } from "./shared-tokens";
import { usePressable } from "./use-pressable";
import { useEnterStyles, type ScreenPhase } from "./use-screen-transition";

/**
 * 各 screen 共用的 chrome 组件:Header / CloseButton / SecondaryButton。
 * 单独抽这个文件避免 save-screen 反向依赖 settings-screen。
 */

// ---------- Header ----------

export const ScreenHeader: React.FC<{
  eyebrow: string;
  title: string;
  phase: ScreenPhase;
  rightSlot?: React.ReactNode;
}> = ({ eyebrow, title, rightSlot }) => {
  const titleStyles = useEnterStyles({
    hidden: { opacity: 0, transform: "translateX(-16px)" },
    delay: 40,
  });
  const lineStyles = useEnterStyles({
    hidden: { opacity: 0, transform: "scaleX(0)" },
    delay: 180,
  });
  const rightStyles = useEnterStyles({
    hidden: { opacity: 0, transform: "translateY(10px)" },
    delay: 120,
  });

  return (
    <header
      style={{
        padding: "48px 80px 32px",
        display: "flex",
        alignItems: "flex-end",
        gap: 24,
      }}
    >
      <div style={titleStyles}>
        <div
          style={{
            fontFamily: tokens.fontMono,
            fontSize: 11,
            letterSpacing: "0.36em",
            textTransform: "uppercase",
            color: tokens.accent,
            marginBottom: 12,
            fontWeight: 600,
          }}
        >
          {eyebrow}
        </div>
        <h2
          style={{
            fontFamily: tokens.fontDisplay,
            fontSize: "clamp(40px, 4.4vw, 60px)",
            fontWeight: 700,
            margin: 0,
            letterSpacing: "0.005em",
            lineHeight: 1.05,
          }}
        >
          {title}
        </h2>
        <div
          style={{
            marginTop: 16,
            width: 64,
            height: 3,
            background: tokens.accent,
            borderRadius: 999,
            transformOrigin: "left center",
            boxShadow: `0 0 12px ${tokens.accentGlow}`,
            ...lineStyles,
          }}
        />
      </div>
      <div
        style={{
          marginLeft: "auto",
          display: "flex",
          alignItems: "center",
          gap: 12,
          ...rightStyles,
        }}
      >
        {rightSlot}
      </div>
    </header>
  );
};

// ---------- 通用按钮 ----------

export const SecondaryButton: React.FC<{
  onClick: () => void;
  children: React.ReactNode;
}> = ({ onClick, children }) => {
  const [hover, setHover] = useState(false);
  const press = usePressable();
  return (
    <button
      onClick={onClick}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={(e) => {
        setHover(false);
        press.handlers.onPointerLeave(e as unknown as React.PointerEvent);
      }}
      onPointerDown={press.handlers.onPointerDown}
      style={{
        appearance: "none",
        background: hover ? tokens.bgElevated : tokens.bgSurface,
        border: `1px solid ${hover ? tokens.borderRegular : tokens.borderSubtle}`,
        borderRadius: tokens.radiusSm,
        height: 44,
        padding: "0 22px",
        color: tokens.textPrimary,
        fontFamily: tokens.fontUI,
        fontSize: 14,
        fontWeight: 600,
        letterSpacing: "0.04em",
        cursor: "default",
        transform: press.pressed
          ? "scale(0.96)"
          : hover
            ? "translateY(-1px)"
            : "translateY(0)",
        transition: `background ${tokens.durFast}ms ${tokens.easeOut}, border-color ${tokens.durFast}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}`,
      }}
    >
      {children}
    </button>
  );
};

export const CloseButton: React.FC<{ onClick: () => void }> = ({ onClick }) => {
  const [hover, setHover] = useState(false);
  const press = usePressable();
  return (
    <button
      onClick={onClick}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={(e) => {
        setHover(false);
        press.handlers.onPointerLeave(e as unknown as React.PointerEvent);
      }}
      onPointerDown={press.handlers.onPointerDown}
      aria-label="关闭"
      style={{
        appearance: "none",
        background: hover ? tokens.bgElevated : tokens.bgSurface,
        border: `1px solid ${hover ? tokens.borderRegular : tokens.borderSubtle}`,
        borderRadius: tokens.radiusSm,
        width: 44,
        height: 44,
        color: tokens.textPrimary,
        cursor: "default",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        transform: press.pressed
          ? "scale(0.92) rotate(90deg)"
          : hover
            ? "rotate(90deg)"
            : "rotate(0)",
        transition: `background ${tokens.durFast}ms ${tokens.easeOut}, border-color ${tokens.durFast}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}`,
      }}
    >
      <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden>
        <path
          d="M3 3l10 10M13 3L3 13"
          stroke="currentColor"
          strokeWidth="1.8"
          strokeLinecap="round"
        />
      </svg>
    </button>
  );
};
