import React, { useEffect, useRef, useState } from "react";
import {
  Extension,
  INTERNAL_SYSTEM_SLOT,
  extension,
  settings,
  useExtensionContext,
  type ExtensionContext,
  type SettingsBuilder,
} from "@avg-studio/sdk";
import { tokens } from "./shared-tokens";
import {
  useScreenTransition,
  useOverlayStyles,
  useEnterStyles,
  type ScreenPhase,
} from "./use-screen-transition";
import { usePressable } from "./use-pressable";
import { ScreenHeader, CloseButton } from "./screen-chrome";

/**
 * 历史画面 —— 大气版 + 全条目 stagger 入场。
 *
 * 入场:
 *   - overlay backdrop blur 0→24
 *   - header 滑入
 *   - 时间线竖线从上往下展开
 *   - 历史条目逐条 stagger(只对最后 12 条做 stagger,避免几百条都跑动画卡)
 *
 * hover 整行高亮 + 时间线节点放大发光,语音按钮 press 反馈。
 */

const HistoryScreenComponent: React.FC = () => {
  const ctx = useExtensionContext();

  const snapshot = ctx.history.useSnapshot();
  // ctx 已 scope 到 (extId, "history-screen"),get 自动加 "history-screen." 前缀
  const allowVoiceReplay =
    ctx.settings.get<boolean>("allowVoiceReplay") ?? true;
  const max = ctx.settings.get<number>("maxEntries") ?? 200;

  const { phase, requestClose } = useScreenTransition(ctx, "history-screen");

  const entries = snapshot.entries.slice(-max);
  const listRef = useRef<HTMLDivElement>(null);

  // mount 时滚到底部(让最新一条可见)
  // 等入场动画跑一会儿再滚,避免 stagger 入场和滚动冲突
  useEffect(() => {
    const el = listRef.current;
    if (!el) return;
    const t = window.setTimeout(() => {
      el.scrollTop = el.scrollHeight;
    }, 100);
    return () => window.clearTimeout(t);
  }, [entries.length]);

  // ESC / 中键关闭
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") requestClose();
    };
    const onAux = (e: MouseEvent) => {
      if (e.button === 1) {
        e.preventDefault();
        requestClose();
      }
    };
    window.addEventListener("keydown", onKey);
    window.addEventListener("auxclick", onAux);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("auxclick", onAux);
    };
  }, [requestClose]);

  // 只对最后 N 条做 stagger,前面的瞬时显示
  const STAGGER_COUNT = 12;
  const staggerStart = Math.max(0, entries.length - STAGGER_COUNT);

  const overlayStyles = useOverlayStyles(phase);
  const timelineStyles = useEnterStyles({
    hidden: { opacity: 0, transform: "scaleY(0)" },
    delay: 120,
    duration: tokens.durSlow + 80,
  });
  const emptyStyles = useEnterStyles({
    hidden: { opacity: 0, transform: "translateY(14px)" },
    delay: 180,
  });

  // 右键关闭:跟设置/读档一致 —— 任何 overlay 单击右键即"返回上一层"。
  const onContextMenu = (e: React.MouseEvent) => {
    e.preventDefault();
    requestClose();
  };

  return (
    <div
      onContextMenu={onContextMenu}
      style={{
        position: "absolute",
        inset: 0,
        background: tokens.bgOverlayStrong,
        backdropFilter: "blur(28px)",
        WebkitBackdropFilter: "blur(28px)",
        color: tokens.textPrimary,
        fontFamily: tokens.fontUI,
        display: "flex",
        flexDirection: "column",
        willChange: "opacity",
        ...overlayStyles,
      }}
    >
      <ScreenHeader
        eyebrow="History"
        title="历史回顾"
        phase={phase}
        rightSlot={
          <>
            <span
              style={{
                fontFamily: tokens.fontMono,
                fontSize: 14,
                color: tokens.textMuted,
                fontWeight: 600,
                fontVariantNumeric: "tabular-nums",
                marginRight: 4,
              }}
            >
              {entries.length} 条
            </span>
            <CloseButton onClick={requestClose} />
          </>
        }
      />

      <div
        ref={listRef}
        className="avg-shell-scrollbar"
        style={{
          flex: 1,
          overflowY: "auto",
          padding: "24px 80px 80px",
        }}
      >
        <div
          style={{
            maxWidth: 880,
            margin: "0 auto",
            position: "relative",
          }}
        >
          {/* 时间线竖线 */}
          <div
            style={{
              position: "absolute",
              left: 156,
              top: 8,
              bottom: 8,
              width: 1.5,
              background: `linear-gradient(180deg, transparent 0%, ${tokens.borderRegular} 8%, ${tokens.borderRegular} 92%, transparent 100%)`,
              transformOrigin: "top",
              ...timelineStyles,
            }}
          />

          {entries.length === 0 && (
            <div
              style={{
                textAlign: "center",
                marginTop: 100,
                fontFamily: tokens.fontDisplay,
                fontSize: 22,
                color: tokens.textFaint,
                fontWeight: 500,
                ...emptyStyles,
              }}
            >
              暂无历史记录
            </div>
          )}

          {entries.map((entry, idx) => {
            const shouldStagger = idx >= staggerStart;
            const staggerDelay = shouldStagger
              ? 140 + (idx - staggerStart) * 30
              : 0;
            return (
              <HistoryEntry
                key={entry.uuid ?? idx}
                speaker={entry.name}
                text={entry.text}
                voiceUri={allowVoiceReplay ? entry.voiceUri : undefined}
                isChoice={!!entry.isChoice}
                onReplay={(uri) => void ctx.history.replayVoice(uri)}
                animationDelay={staggerDelay}
                shouldAnimate={shouldStagger}
              />
            );
          })}
        </div>
      </div>
    </div>
  );
};

// ---------- HistoryEntry ----------

const HistoryEntry: React.FC<{
  speaker?: string;
  text: string;
  voiceUri?: string;
  isChoice: boolean;
  onReplay: (uri: string) => void;
  animationDelay: number;
  /** 是否参与入场动画(只有最后 STAGGER_COUNT 条) */
  shouldAnimate: boolean;
}> = ({
  speaker,
  text,
  voiceUri,
  isChoice,
  onReplay,
  animationDelay,
  shouldAnimate,
}) => {
  const [hover, setHover] = useState(false);
  // hook 始终调用,style 在 shouldAnimate=false 时不应用
  const wrapperStyles = useEnterStyles({
    hidden: shouldAnimate
      ? { opacity: 0, transform: "translateY(12px) scale(0.98)" }
      : {},
    delay: animationDelay,
  });

  return (
    <div style={shouldAnimate ? wrapperStyles : undefined}>
    <div
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      style={{
        display: "grid",
        gridTemplateColumns: "144px 24px 1fr auto",
        gap: 16,
        padding: "18px 16px",
        position: "relative",
        alignItems: "start",
        borderRadius: tokens.radiusMd,
        background: hover ? tokens.accentSoft : "transparent",
        marginLeft: -16,
        marginRight: -16,
        transition: `background ${tokens.durBase}ms ${tokens.easeOut}`,
      }}
    >
      {/* 角色名 */}
      <div
        style={{
          fontFamily: tokens.fontUI,
          fontSize: 15,
          fontWeight: 700,
          letterSpacing: "0.02em",
          color: isChoice ? tokens.accent : tokens.textPrimary,
          textAlign: "right",
          paddingTop: 2,
          paddingRight: 8,
        }}
      >
        {isChoice ? "▸ 选择" : speaker || ""}
      </div>

      {/* 时间线节点 */}
      <div
        style={{
          position: "relative",
          height: "100%",
          display: "flex",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            width: 10,
            height: 10,
            marginTop: 8,
            borderRadius: "50%",
            background: hover || isChoice ? tokens.accent : tokens.borderStrong,
            border: `2.5px solid ${tokens.bgOverlayStrong}`,
            transition: `background ${tokens.durFast}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}`,
            transform: hover ? "scale(1.4)" : "scale(1)",
            boxShadow: hover
              ? `0 0 0 6px ${tokens.accentSoft}, 0 0 16px ${tokens.accentGlow}`
              : "none",
          }}
        />
      </div>

      {/* 文字 */}
      <div
        style={{
          fontSize: 16,
          lineHeight: 1.7,
          color: isChoice ? tokens.accent : tokens.textPrimary,
          fontStyle: isChoice ? "normal" : "normal",
          fontWeight: isChoice ? 600 : 400,
          paddingTop: 0,
          textWrap: "pretty",
        }}
      >
        {text}
      </div>

      {/* 语音重播 */}
      <div style={{ paddingTop: 0 }}>
        {voiceUri && (
          <VoiceButton
            onClick={() => onReplay(voiceUri)}
            highlight={hover}
          />
        )}
      </div>
    </div>
    </div>
  );
};

const VoiceButton: React.FC<{
  onClick: () => void;
  highlight: boolean;
}> = ({ onClick, highlight }) => {
  const press = usePressable();
  return (
    <button
      onClick={onClick}
      onPointerDown={press.handlers.onPointerDown}
      onPointerLeave={press.handlers.onPointerLeave}
      aria-label="重播语音"
      title="重播语音"
      style={{
        appearance: "none",
        width: 36,
        height: 36,
        borderRadius: "50%",
        border: `1.5px solid ${highlight ? tokens.borderAccent : tokens.borderSubtle}`,
        background: highlight ? tokens.accentSoft : "transparent",
        color: highlight ? tokens.accent : tokens.textMuted,
        cursor: "default",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        transform: press.pressed ? "scale(0.92)" : "scale(1)",
        transition: `all ${tokens.durFast}ms ${tokens.easeOut}`,
        boxShadow: highlight ? `0 0 12px ${tokens.accentGlow}` : "none",
      }}
    >
      <svg width="13" height="13" viewBox="0 0 13 13" aria-hidden>
        <path
          d="M3 2.5v8l7-4z"
          fill="currentColor"
          stroke="currentColor"
          strokeWidth="0.5"
          strokeLinejoin="round"
        />
      </svg>
    </button>
  );
};

@extension({
  id: "history-screen",
  label: "历史画面",
  exposeUI: false, // 保留呼出快捷键,React 版不再进入 UI 列表
  autonomous: true, // 全局打开历史快捷键由 onRegister 绑定
  /** 2026-05 Internal Extension Points §6.1:声明本 UI 实现"历史"槽位。 */
  supportsSlot: INTERNAL_SYSTEM_SLOT.History,
})
export class HistoryScreen extends Extension {
  // 2026-05 Internal Extension Points:删除 slotUI 字段,改由项目级
  // systemBindings 控制(在 Studio 项目设置 → 系统 面板配置)。
  static settings = settings((s: SettingsBuilder) => ({
    maxEntries: s
      .number("最大历史条数")
      .default(200)
      .range(10, 1000)
      .step(10),
    allowVoiceReplay: s.boolean("允许语音重播").default(true),
    // 注:呼出快捷键由 ctx.input.registerAction (走 KeyBindingSystem) 注册,
    // 玩家在个性化 → 输入按键 tab 改键。
  }));

  /**
   * 注册"打开历史画面"语义动作 + 订阅触发。键位由 KeyBindingSystem 管理:
   *   - default_keys: middleclick (鼠标中键,跟之前 settings 默认一致)
   *   - 玩家在"输入按键"tab 改键 → 自动生效
   */
  static onRegister(ctx: ExtensionContext): void {
    // 2026-05 Internal Extension Points §4.5:扩展贡献的 action id 必须以
    // 扩展自身 id (avg.internal.default-shell) 为前缀。
    ctx.input.registerAction({
      id: "avg.internal.default-shell.open-history",
      label: "呼出历史画面",
      defaultKeys: ["middleclick"]
    });
    ctx.input.onAction("avg.internal.default-shell.open-history", () => {
      // 2026-05 Internal Extension Points:走系统槽位而非 settings.slotUI。
      // 默认绑定 internal.system.history → 本扩展自己的 history-screen。
      // 用户在 Studio 替换成其他扩展提供的历史 UI 也会被尊重。
      void ctx.system.invoke(INTERNAL_SYSTEM_SLOT.History, undefined, {
        modal: true,
      });
    });
  }

  render() {
    return { component: HistoryScreenComponent, props: {} };
  }
}
