import React, { useEffect, useRef, useState } from "react";
import {
  Extension,
  extension,
  method,
  settings,
  defineSave,
  useExtensionContext,
  INTERNAL_SYSTEM_SLOT,
  type ExtensionContext,
  type SaveAPI,
  type SettingsBuilder,
  type GalleryLayer,
} from "@avg-studio/sdk";
import { manifest } from "./manifest";
import { tokens } from "./shared-tokens";
import {
  useScreenTransition,
  useOverlayStyles,
  useEnterStyles,
} from "./use-screen-transition";
import { usePressable } from "./use-pressable";
import { ScreenHeader, CloseButton } from "./screen-chrome";
import {
  parseLayersJson,
  isValidEntry,
  resolveGalleryTitle,
  deriveCoverImage,
  isValidFragmentEntry,
  isValidMusicEntry,
  optionalText,
  type GalleryEntry,
  type FragmentGalleryEntry,
  type MusicGalleryEntry,
} from "./gallery-entry-helpers";

/**
 * 鉴赏画面 —— 统一模块基类(Extension)的完整示范:
 * 一个类 = 界面(render)+ 方法(addToGallery)+ 存档(saveSchema)+ 设置(settings)。
 *
 * 数据流(2026-06-14 改为「选场景」):
 *   剧本 Action block「加入鉴赏」→ addToGallery.run → 按 unlockScope 写入
 *   shared / slot 两个存档桶之一 → 界面合并两桶,缩略图用 layers CSS 叠层,
 *   点开大图用 ctx.sceneRender.mount 起隔离临时引擎实时渲染场景(为后续天气特效铺路)。
 *
 * 双桶设计:saveSchema 的 persistence 是静态声明,无法运行时切换,
 * 所以 shared / slot 各开一个桶,settings.unlockScope 只决定**新解锁**写哪个桶;
 * 界面永远取并集 —— 作者中途切换设置不会丢已解锁数据。
 */

/** this.save 的强类型视图(method 的 this 是 ExtensionBase,需显式收窄)。 */
type GallerySaveMap = {
  unlockedShared: readonly GalleryEntry[];
  unlockedSlot: readonly GalleryEntry[];
  unlockedMusicShared: readonly MusicGalleryEntry[];
  unlockedMusicSlot: readonly MusicGalleryEntry[];
  unlockedFragmentsShared: readonly FragmentGalleryEntry[];
  unlockedFragmentsSlot: readonly FragmentGalleryEntry[];
};

const UI_ID = "gallery-screen";

// saveSchema 字段在 VariableSystem 里的全名是 `<extensionId>.<key>`
// (见 studio/runtime/setup-extension-save.ts)。this.save.useValue 尚未接通
// React,组件层直接走这条底层通道做响应式订阅。
const SHARED_VAR = `${manifest.id}.unlockedShared`;
const SLOT_VAR = `${manifest.id}.unlockedSlot`;

// ---------- 数据读取 ----------

/**
 * 读两桶并集(entryId 去重,shared 桶优先)。
 * ctx.variables.useValue 订阅 variable:changed,解锁发生时图墙自动刷新。
 */
function useGalleryEntries(ctx: ExtensionContext): GalleryEntry[] {
  const [sharedRaw] = ctx.variables.useValue(SHARED_VAR);
  const [slotRaw] = ctx.variables.useValue(SLOT_VAR);
  // VariableValue 类型没覆盖 list,但 saveSchema 的 list 字段实际存的就是数组
  const shared =
    (sharedRaw as unknown as readonly GalleryEntry[] | undefined) ?? [];
  const slot =
    (slotRaw as unknown as readonly GalleryEntry[] | undefined) ?? [];

  const seen = new Set<string>();
  const merged: GalleryEntry[] = [];
  for (const entry of [...shared, ...slot]) {
    // 脏条目防御:用 isValidEntry 集中校验(entryId/sceneId/layers 都得在)。
    // 历史数据/参数没填完整就跑过的 block 可能写入坏条目;过滤掉只是不显示,不黑屏。
    if (!isValidEntry(entry)) continue;
    if (seen.has(entry.entryId)) continue;
    seen.add(entry.entryId);
    merged.push(entry);
  }
  return merged;
}

// ---------- 主组件 ----------

const GalleryScreenComponent: React.FC = () => {
  const ctx = useExtensionContext();
  const entries = useGalleryEntries(ctx);
  const { phase, requestClose } = useScreenTransition(ctx, UI_ID);

  /** 当前在 lightbox 里查看的条目;null = 图墙模式。 */
  const [viewing, setViewing] = useState<GalleryEntry | null>(null);

  // ESC / 鼠标中键:lightbox 打开时不在这里处理(Lightbox 自己监听,走它内部
  // 的两段式淡出关闭),只关图墙模式下的整个画面。否则会跳过 Lightbox 的淡出。
  useEffect(() => {
    if (viewing) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") requestClose();
    };
    const onAux = (e: MouseEvent) => {
      if (e.button === 1) {
        e.preventDefault();
        requestClose();
      }
    };
    window.addEventListener("keydown", onKey);
    window.addEventListener("auxclick", onAux);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("auxclick", onAux);
    };
  }, [viewing, requestClose]);

  // 右键 = 返回上一层(跟历史/设置/读档一致的 overlay 约定)。
  // 同样:lightbox 打开时它自己接管右键,不在这里 setViewing(null) 跳过淡出。
  const onContextMenu = (e: React.MouseEvent) => {
    e.preventDefault();
    if (viewing) return;
    requestClose();
  };

  const overlayStyles = useOverlayStyles(phase);
  const emptyStyles = useEnterStyles({
    hidden: { opacity: 0, transform: "translateY(14px)" },
    delay: 180,
  });

  // 入场 stagger:前 12 张逐张错峰,之后的统一在最后一拍一起浮现
  const STAGGER_COUNT = 12;

  return (
    <div
      onContextMenu={onContextMenu}
      style={{
        position: "absolute",
        inset: 0,
        background: tokens.bgOverlayStrong,
        backdropFilter: "blur(28px)",
        WebkitBackdropFilter: "blur(28px)",
        color: tokens.textPrimary,
        fontFamily: tokens.fontUI,
        display: "flex",
        flexDirection: "column",
        willChange: "opacity",
        ...overlayStyles,
      }}
    >
      <ScreenHeader
        eyebrow="Gallery"
        title="鉴赏室"
        phase={phase}
        rightSlot={
          <>
            <span
              style={{
                fontFamily: tokens.fontMono,
                fontSize: 14,
                color: tokens.textMuted,
                fontWeight: 600,
                fontVariantNumeric: "tabular-nums",
                marginRight: 4,
              }}
            >
              {entries.length} 张
            </span>
            <CloseButton onClick={requestClose} />
          </>
        }
      />

      <div
        className="avg-shell-scrollbar"
        style={{
          flex: 1,
          overflowY: "auto",
          padding: "24px 80px 80px",
        }}
      >
        <div style={{ maxWidth: 1160, margin: "0 auto" }}>
          {entries.length === 0 ? (
            <div
              style={{
                textAlign: "center",
                marginTop: 100,
                fontFamily: tokens.fontDisplay,
                fontSize: 22,
                color: tokens.textFaint,
                fontWeight: 500,
                ...emptyStyles,
              }}
            >
              还没有解锁任何鉴赏内容
            </div>
          ) : (
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "repeat(auto-fill, minmax(240px, 1fr))",
                gap: 20,
              }}
            >
              {entries.map((entry, idx) => (
                <GalleryCard
                  key={entry.entryId}
                  entry={entry}
                  ctx={ctx}
                  animationDelay={140 + Math.min(idx, STAGGER_COUNT) * 36}
                  onOpen={() => setViewing(entry)}
                />
              ))}
            </div>
          )}
        </div>
      </div>

      {viewing && (
        <Lightbox
          entry={viewing}
          ctx={ctx}
          onClose={() => setViewing(null)}
        />
      )}
    </div>
  );
};

// ---------- 缩略图卡片(layers CSS 叠层渲染) ----------

const GalleryCard: React.FC<{
  entry: GalleryEntry;
  ctx: ExtensionContext;
  animationDelay: number;
  onOpen: () => void;
}> = ({ entry, ctx, animationDelay, onOpen }) => {
  const [hover, setHover] = useState(false);
  const press = usePressable();
  const enterStyles = useEnterStyles({
    hidden: { opacity: 0, transform: "translateY(16px) scale(0.97)" },
    delay: animationDelay,
  });

  return (
    <div style={enterStyles}>
      <div
        onClick={onOpen}
        onMouseEnter={() => setHover(true)}
        onMouseLeave={() => {
          setHover(false);
          press.handlers.onPointerLeave();
        }}
        onPointerDown={press.handlers.onPointerDown}
        role="button"
        aria-label={entry.title}
        style={{
          position: "relative",
          aspectRatio: "16 / 9",
          borderRadius: tokens.radiusMd,
          overflow: "hidden",
          background: tokens.bgSunken,
          border: `1px solid ${hover ? tokens.borderAccent : tokens.borderSubtle}`,
          cursor: "default",
          transform: press.pressed
            ? "scale(0.97)"
            : hover
              ? "translateY(-2px)"
              : "translateY(0)",
          boxShadow: hover
            ? `0 8px 28px rgba(0, 0, 0, 0.4), 0 0 16px ${tokens.accentGlow}`
            : "0 2px 10px rgba(0, 0, 0, 0.25)",
          transition: `border-color ${tokens.durFast}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}, box-shadow ${tokens.durBase}ms ${tokens.easeOut}`,
        }}
      >
        <LayeredThumb
          layers={entry.layers}
          ctx={ctx}
          hover={hover}
          alt={entry.title}
        />
        {/* 底部标题条:渐变压暗保证任意图片上文字可读 */}
        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            bottom: 0,
            padding: "26px 12px 10px",
            background:
              "linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,0.72) 100%)",
            fontSize: 13,
            fontWeight: 600,
            letterSpacing: "0.02em",
            color: hover ? tokens.accent : tokens.textPrimary,
            whiteSpace: "nowrap",
            overflow: "hidden",
            textOverflow: "ellipsis",
            transition: `color ${tokens.durFast}ms ${tokens.easeOut}`,
          }}
        >
          {entry.title}
        </div>
      </div>
    </div>
  );
};

/**
 * 多图层缩略图叠加 —— 用 absolute 定位的多个 <img> 按 layers 顺序堆叠。
 * layers[0] 最底,后面的盖上去(跟引擎场景图层语义一致)。
 *
 * 缩略图是静态展示,不做视差/transform 变换,只要"看到这张图什么样"即可。
 * 大图渲染则在 Lightbox 里走临时引擎,有完整视差与未来天气特效。
 */
const LayeredThumb: React.FC<{
  layers: GalleryLayer[];
  ctx: ExtensionContext;
  hover: boolean;
  alt: string;
}> = ({ layers, ctx, hover, alt }) => {
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        transform: hover ? "scale(1.05)" : "scale(1)",
        transition: `transform ${tokens.durSlow}ms ${tokens.easeOut}`,
      }}
    >
      {layers.map((layer, i) => {
        const url = ctx.asset.resolve(layer.assetPath).url;
        return (
          <img
            key={`${i}-${layer.assetPath}`}
            src={url}
            alt={i === 0 ? alt : ""}
            draggable={false}
            style={{
              position: "absolute",
              inset: 0,
              width: "100%",
              height: "100%",
              objectFit: "cover",
              display: "block",
            }}
          />
        );
      })}
    </div>
  );
};

// ---------- Lightbox 大图(临时引擎实时渲染场景) ----------

const Lightbox: React.FC<{
  entry: GalleryEntry;
  ctx: ExtensionContext;
  onClose: () => void;
}> = ({ entry, ctx, onClose }) => {
  const backdropStyles = useEnterStyles({
    hidden: { opacity: 0 },
    duration: tokens.durBase,
  });
  const figureStyles = useEnterStyles({
    hidden: { opacity: 0, transform: "scale(0.96) translateY(10px)" },
    delay: 40,
  });

  const stageRef = useRef<HTMLDivElement | null>(null);
  const [renderError, setRenderError] = useState<string | null>(null);

  // 两段式关闭:用户点关闭 → setClosing(true) → 引擎画面 + backdrop CSS 透明
  // 度淡出 → 淡出动画跑完才真正调外部 onClose → React 卸载 Lightbox → 引擎
  // destroy。这样引擎销毁那一瞬间(不可避免有白闪/中间态)发生在 stage 已经
  // 透明了的状态下,用户看不到。
  const [closing, setClosing] = useState(false);
  const closeTimerRef = useRef<number | null>(null);
  const CLOSE_FADE_MS = tokens.durBase; // 跟 enter 同节奏
  const requestClose = () => {
    if (closing) return;
    setClosing(true);
    closeTimerRef.current = window.setTimeout(() => {
      onClose();
    }, CLOSE_FADE_MS);
  };
  useEffect(() => {
    return () => {
      if (closeTimerRef.current != null) {
        clearTimeout(closeTimerRef.current);
      }
    };
  }, []);

  // Lightbox 自己监听 ESC / 中键 / 右键 → 统一走两段式关闭。
  // 父组件的 ESC handler 在 viewing 时已经 return,这里独占。
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") requestClose();
    };
    const onAux = (e: MouseEvent) => {
      if (e.button === 1) {
        e.preventDefault();
        requestClose();
      }
    };
    window.addEventListener("keydown", onKey);
    window.addEventListener("auxclick", onAux);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("auxclick", onAux);
    };
    // requestClose 是 closure(闭包),每次 render 重新建,但只读 closing 守卫,
    // 多调一次最多就是 setTimeout 多一个被 clearTimeout 清掉,无副作用。
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 起一个隔离临时引擎渲染场景。卸载时 dispose,靠 identity check 保证不污染主引擎。
  useEffect(() => {
    if (!stageRef.current) return;
    const stage = stageRef.current;
    let handle: { dispose(): void } | null = null;
    let cancelled = false;
    (async () => {
      try {
        const h = await ctx.sceneRender.mount(stage, entry.layers, {
          // 场景图按 AVG 常规呈现 = 铺满容器、超出裁掉(cover),
          // contain 会留黑边导致用户看到"显示不全"
          displayType: "cover",
        });
        if (cancelled) {
          h.dispose();
          return;
        }
        handle = h;
      } catch (err) {
        console.error("[gallery] 大图临时引擎渲染失败:", err);
        if (!cancelled) {
          setRenderError(
            err instanceof Error ? err.message : "场景渲染失败",
          );
        }
      }
    })();
    return () => {
      cancelled = true;
      handle?.dispose();
      // 不要在这里手动清 stage 子节点 —— engine.destroy 会自己 React unmount
      // + holderElement.empty(),提前 removeChild 会让引擎 unmount 时
      // "node to be removed is not a child of this node" 报错。让引擎自管。
    };
  }, [ctx.sceneRender, entry.layers]);

  return (
    <div
      onClick={requestClose}
      onContextMenu={(e) => {
        // 右键也走两段式淡出关闭,保持跟图墙模式右键返回的一致体验
        e.preventDefault();
        e.stopPropagation();
        requestClose();
      }}
      style={{
        position: "absolute",
        inset: 0,
        zIndex: 20,
        background: "rgba(0, 0, 0, 0.88)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        // 关闭态:整层 fade out,覆盖引擎 destroy 的中间态白闪
        ...(closing
          ? {
              opacity: 0,
              transition: `opacity ${CLOSE_FADE_MS}ms ${tokens.easeOut}`,
              pointerEvents: "none",
            }
          : backdropStyles),
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          maxWidth: "88%",
          ...(closing
            ? {
                // 关闭态:figure 一并下沉淡出,跟 enter 动画对称
                opacity: 0,
                transform: "scale(0.96) translateY(10px)",
                transition: `opacity ${CLOSE_FADE_MS}ms ${tokens.easeOut}, transform ${CLOSE_FADE_MS}ms ${tokens.easeOut}`,
              }
            : figureStyles),
        }}
      >
        <div
          ref={stageRef}
          style={{
            position: "relative",
            width: "min(88vw, 1280px)",
            aspectRatio: "16 / 9",
            maxHeight: "72vh",
            borderRadius: tokens.radiusLg,
            border: `1px solid ${tokens.borderSubtle}`,
            boxShadow: "0 24px 80px rgba(0, 0, 0, 0.6)",
            background: "#000",
            overflow: "hidden",
          }}
        >
          {renderError && (
            <div
              style={{
                position: "absolute",
                inset: 0,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                color: tokens.textMuted,
                fontSize: 14,
                padding: 24,
                textAlign: "center",
              }}
            >
              场景渲染失败:{renderError}
            </div>
          )}
        </div>
        <div
          style={{
            marginTop: 20,
            fontFamily: tokens.fontDisplay,
            fontSize: 20,
            fontWeight: 600,
            letterSpacing: "0.01em",
            textAlign: "center",
          }}
        >
          {entry.title}
        </div>
      </div>

      <div
        onClick={(e) => e.stopPropagation()}
        style={{ position: "absolute", top: 28, right: 32 }}
      >
        <CloseButton onClick={requestClose} />
      </div>
    </div>
  );
};

// ---------- 模块类 ----------

@extension({
  id: "gallery-screen",
  label: "鉴赏管理",
  exposeUI: false, // 保留鉴赏方法和存档数据,React 版不再进入 UI 列表
  /** 声明本 UI 实现"鉴赏"槽位,Studio 系统槽位面板据此列为候选。 */
  supportsSlot: INTERNAL_SYSTEM_SLOT.Gallery,
})
export class GalleryScreen extends Extension {
  // 双桶存档:persistence 是静态声明,无法运行时切换,所以 shared/slot 各一个桶,
  // settings.unlockScope 决定写入哪个桶,界面合并两桶并集显示(切设置不丢数据)。
  static saveSchema = defineSave({
    unlockedShared: {
      type: "list",
      persistence: "shared",
      default: [] as GalleryEntry[],
    },
    unlockedSlot: {
      type: "list",
      persistence: "slot",
      default: [] as GalleryEntry[],
    },
    unlockedMusicShared: {
      type: "list",
      persistence: "shared",
      default: [] as MusicGalleryEntry[],
    },
    unlockedMusicSlot: {
      type: "list",
      persistence: "slot",
      default: [] as MusicGalleryEntry[],
    },
    unlockedFragmentsShared: {
      type: "list",
      persistence: "shared",
      default: [] as FragmentGalleryEntry[],
    },
    unlockedFragmentsSlot: {
      type: "list",
      persistence: "slot",
      default: [] as FragmentGalleryEntry[],
    },
  });

  // 设置只管本模块的数据语义。标题画面菜单项的显隐/文案归 title-screen
  // (谁的界面谁做主),见 title-screen 的 showGallery / galleryLabel。
  static settings = settings((s: SettingsBuilder) => ({
    unlockScope: s
      .enum("解锁记录范围", ["shared", "slot"] as const)
      .labels({ shared: "全局共享(跨存档)", slot: "跟随存档" })
      .default("shared")
      .describe(
        "新解锁的鉴赏条目记到哪里:全局共享 = 任意周目解锁全局可见;" +
          "跟随存档 = 只在当前存档可见。已解锁条目不受切换影响。",
      ),
  }));

  static addToGallery = method({
    id: "add-to-gallery",
    title: "加入鉴赏",
    description: "把一个场景解锁到鉴赏室,玩家可在鉴赏界面查看",
    schema: {
      // scene 字段值是 sceneId 字符串;Inspector 选场景时同步把 layers 快照
      // 写进兄弟字段 _sceneLayers、场景名写进 _sceneName(都是内部兄弟字段)。
      scene: { type: "scene", label: "鉴赏场景", required: true },
      // 选填:不填时缺省用场景名称(而非 sceneId)。
      title: { type: "string", label: "标题(选填,默认用场景名)" },
    },
    run(_ctx, params) {
      // 参数防御:scene 是 required,但运行时没有表单强制 —— 创作者插了
      // block 没填完参数就跑预览,params 会缺字段。缺了就 warn + 跳过。
      const sceneId =
        typeof params.scene === "string" ? params.scene.trim() : "";
      if (!sceneId) {
        console.warn("[gallery] 「加入鉴赏」缺少场景,已跳过:", params);
        return;
      }
      // layers 快照从兄弟字段读;字段名 _sceneLayers 跟 SceneLitControl 写入端约定。
      // 兼容:Studio 显示 title 可以再加(目前不强求,用 sceneId 兜底)。
      const layersRaw = (params as Record<string, unknown>)._sceneLayers;
      const layers = parseLayersJson(
        typeof layersRaw === "string" ? layersRaw : undefined,
      );
      if (layers.length === 0) {
        console.warn(
          "[gallery] 「加入鉴赏」layers 快照缺失或为空,已跳过:",
          { sceneId },
        );
        return;
      }
      // sceneId 做去重 key + 内部条目标识(场景本身唯一,对创作者透明)。
      const entryId = sceneId;

      const save = this.save as unknown as SaveAPI<GallerySaveMap>;
      const scope =
        _ctx.settings.get<"shared" | "slot">("unlockScope") ?? "shared";

      const shared = save.get("unlockedShared") ?? [];
      const slot = save.get("unlockedSlot") ?? [];

      // 幂等:两桶并集里已存在同 entryId → 跳过,不重复解锁
      const exists = [...shared, ...slot].some((e) => e?.entryId === entryId);
      if (exists) return;

      // 标题三级回退:创作者填的 title → Inspector 写入的场景名 → sceneId 兜底。
      const p = params as Record<string, unknown>;
      const title = resolveGalleryTitle({
        customTitle: p.title,
        sceneName: p._sceneName,
        sceneId,
      });

      const entry: GalleryEntry = {
        entryId,
        title,
        sceneId,
        layers,
        // 拍平一张顶层封面,供可视化「数据列表」版鉴赏墙绑图(它取不到嵌套 layers)
        coverImage: deriveCoverImage(layers),
      };

      // 写入时顺手清掉桶里的历史脏条目(自愈)。save 的 list 是 readonly,整体替换写回。
      if (scope === "slot") {
        save.set("unlockedSlot", [...slot.filter(isValidEntry), entry]);
      } else {
        save.set("unlockedShared", [...shared.filter(isValidEntry), entry]);
      }
    },
  });

  static removeFromGallery = method({
    id: "remove-from-gallery",
    title: "移除鉴赏",
    description: "从鉴赏室移除指定场景对应的条目(两个记录桶都会找)",
    schema: {
      scene: { type: "scene", label: "鉴赏场景", required: true },
    },
    run(_ctx, params) {
      const sceneId =
        typeof params.scene === "string" ? params.scene.trim() : "";
      if (!sceneId) {
        console.warn("[gallery] 「移除鉴赏」缺少场景,已跳过");
        return;
      }
      const save = this.save as unknown as SaveAPI<GallerySaveMap>;
      // 按 sceneId 命中删除;顺手清无效条目自愈。
      const keep = (e: GalleryEntry) =>
        isValidEntry(e) && e.sceneId !== sceneId;
      save.set(
        "unlockedShared",
        (save.get("unlockedShared") ?? []).filter(keep),
      );
      save.set(
        "unlockedSlot",
        (save.get("unlockedSlot") ?? []).filter(keep),
      );
    },
  });

  static addMusicToGallery = method({
    id: "add-music-to-gallery",
    title: "加入音乐鉴赏",
    description: "解锁一首音乐，玩家可在鉴赏界面试听",
    schema: {
      audio: {
        type: "asset",
        assetType: "audio",
        label: "音乐资源",
        required: true,
      },
      title: { type: "string", label: "曲名（选填）" },
      artist: { type: "string", label: "作者（选填）" },
      description: {
        type: "string",
        label: "曲目说明（选填）",
        multiline: true,
      },
    },
    run(ctx, params) {
      const audioUri = optionalText(params.audio);
      if (!audioUri) {
        console.warn("[gallery] 「加入音乐鉴赏」缺少音乐资源，已跳过");
        return;
      }

      const title =
        optionalText(params.title) ??
        audioUri.split(/[\\/]/).pop()?.replace(/\.[^.]+$/, "") ??
        audioUri;
      const entry: MusicGalleryEntry = {
        entryId: audioUri,
        title,
        audioUri,
        artist: optionalText(params.artist),
        description: optionalText(params.description),
      };
      const save = this.save as unknown as SaveAPI<GallerySaveMap>;
      const shared = save.get("unlockedMusicShared") ?? [];
      const slot = save.get("unlockedMusicSlot") ?? [];
      if ([...shared, ...slot].some((item) => item?.entryId === entry.entryId)) {
        return;
      }
      const scope =
        ctx.settings.get<"shared" | "slot">("unlockScope") ?? "shared";
      if (scope === "slot") {
        save.set("unlockedMusicSlot", [
          ...slot.filter(isValidMusicEntry),
          entry,
        ]);
      } else {
        save.set("unlockedMusicShared", [
          ...shared.filter(isValidMusicEntry),
          entry,
        ]);
      }
    },
  });

  static removeMusicFromGallery = method({
    id: "remove-music-from-gallery",
    title: "移除音乐鉴赏",
    description: "从音乐鉴赏中移除指定音乐（全局与当前存档都会移除）",
    schema: {
      audio: {
        type: "asset",
        assetType: "audio",
        label: "音乐资源",
        required: true,
      },
    },
    run(_ctx, params) {
      const audioUri = optionalText(params.audio);
      if (!audioUri) return;
      const save = this.save as unknown as SaveAPI<GallerySaveMap>;
      const keep = (entry: MusicGalleryEntry) =>
        isValidMusicEntry(entry) && entry.audioUri !== audioUri;
      save.set(
        "unlockedMusicShared",
        (save.get("unlockedMusicShared") ?? []).filter(keep),
      );
      save.set(
        "unlockedMusicSlot",
        (save.get("unlockedMusicSlot") ?? []).filter(keep),
      );
    },
  });

  static addFragmentToGallery = method({
    id: "add-fragment-to-gallery",
    title: "加入片段鉴赏",
    description: "解锁一个剧情片段，玩家可在鉴赏界面重新播放",
    schema: {
      fragment: { type: "fragment", label: "剧情片段", required: true },
      chapterId: { type: "string", label: "章节 ID（跨章节时填写）" },
      title: { type: "string", label: "标题（选填，默认用片段名）" },
      description: {
        type: "string",
        label: "片段说明（选填）",
        multiline: true,
      },
      cover: {
        type: "asset",
        assetType: "image",
        label: "封面图（选填）",
      },
    },
    async run(ctx, params) {
      const fragmentId = optionalText(params.fragment);
      if (!fragmentId) {
        console.warn("[gallery] 「加入片段鉴赏」缺少剧情片段，已跳过");
        return;
      }

      let chapterId = optionalText(params.chapterId);
      let fragmentName: string | undefined;
      try {
        const chapters = await ctx.story.getAllChapters();
        const chapter = chapterId
          ? chapters.find((item) => item.id === chapterId)
          : chapters.find((item) =>
              item.fragments.some((fragment) => fragment.id === fragmentId),
            );
        const fragment = chapter?.fragments.find(
          (item) => item.id === fragmentId,
        );
        chapterId = chapter?.id ?? chapterId;
        fragmentName = optionalText(fragment?.name);
      } catch (error) {
        console.warn("[gallery] 读取片段标题失败，将使用片段 ID", error);
      }

      const entry: FragmentGalleryEntry = {
        entryId: `${chapterId ?? "current"}:${fragmentId}`,
        title: optionalText(params.title) ?? fragmentName ?? fragmentId,
        fragmentId,
        chapterId,
        description: optionalText(params.description),
        coverImage: optionalText(params.cover),
      };
      const save = this.save as unknown as SaveAPI<GallerySaveMap>;
      const shared = save.get("unlockedFragmentsShared") ?? [];
      const slot = save.get("unlockedFragmentsSlot") ?? [];
      if ([...shared, ...slot].some((item) => item?.entryId === entry.entryId)) {
        return;
      }
      const scope =
        ctx.settings.get<"shared" | "slot">("unlockScope") ?? "shared";
      if (scope === "slot") {
        save.set("unlockedFragmentsSlot", [
          ...slot.filter(isValidFragmentEntry),
          entry,
        ]);
      } else {
        save.set("unlockedFragmentsShared", [
          ...shared.filter(isValidFragmentEntry),
          entry,
        ]);
      }
    },
  });

  static removeFragmentFromGallery = method({
    id: "remove-fragment-from-gallery",
    title: "移除片段鉴赏",
    description: "从片段鉴赏中移除指定剧情片段（全局与当前存档都会移除）",
    schema: {
      fragment: { type: "fragment", label: "剧情片段", required: true },
      chapterId: { type: "string", label: "章节 ID（选填）" },
    },
    run(_ctx, params) {
      const fragmentId = optionalText(params.fragment);
      const chapterId = optionalText(params.chapterId);
      if (!fragmentId) return;
      const save = this.save as unknown as SaveAPI<GallerySaveMap>;
      const keep = (entry: FragmentGalleryEntry) =>
        isValidFragmentEntry(entry) &&
        (entry.fragmentId !== fragmentId ||
          (chapterId !== undefined && entry.chapterId !== chapterId));
      save.set(
        "unlockedFragmentsShared",
        (save.get("unlockedFragmentsShared") ?? []).filter(keep),
      );
      save.set(
        "unlockedFragmentsSlot",
        (save.get("unlockedFragmentsSlot") ?? []).filter(keep),
      );
    },
  });

  static clearGallery = method({
    id: "clear-gallery",
    title: "清空鉴赏",
    description: "清空 CG、音乐与片段鉴赏的全部解锁记录（慎用）",
    run() {
      const save = this.save as unknown as SaveAPI<GallerySaveMap>;
      save.set("unlockedShared", []);
      save.set("unlockedSlot", []);
      save.set("unlockedMusicShared", []);
      save.set("unlockedMusicSlot", []);
      save.set("unlockedFragmentsShared", []);
      save.set("unlockedFragmentsSlot", []);
    },
  });

  render() {
    return { component: GalleryScreenComponent, props: {} };
  }
}
