import React, { useEffect, useState } from "react";
import {
  Extension,
  INTERNAL_SYSTEM_SLOT,
  extension,
  settings,
  useExtensionContext,
  type SettingsBuilder,
} from "@avg-studio/sdk";
import { tokens } from "./shared-tokens";
import { usePressable } from "./use-pressable";

/**
 * 标题画面 —— 大气版。
 *
 * 布局原则:
 *   - 菜单立式排在左侧垂直居中(用户要求)
 *   - 顶部细线 + 底部小标签 + 右上版本号 撑起画面四角
 *   - 背景默认透明,让玩家先执行的 scene OP 当背景
 *
 * 大气感来源:
 *   - 菜单 36-44px 衬线 + 数字编号(01/02..),hover 时长贯穿线滑入
 *   - 大幅 negative space + 顶/底/左/右四角细装饰
 */

// 菜单结构(key + 默认文案)。key 是行为标识不暴露给用户;文案通过本模块
// settings 的 startLabel / loadLabel / galleryLabel / settingsLabel / exitLabel
// 让用户覆盖。菜单项的显隐/文案全部归 title-screen 自己管(谁的界面谁做主)。
const MENU_DEFS = [
  { key: "start", settingKey: "startLabel", defaultLabel: "开始游戏" },
  { key: "load", settingKey: "loadLabel", defaultLabel: "读取存档" },
  { key: "gallery", settingKey: "galleryLabel", defaultLabel: "鉴赏" },
  { key: "settings", settingKey: "settingsLabel", defaultLabel: "设置" },
  { key: "exit", settingKey: "exitLabel", defaultLabel: "退出" },
] as const;

type MenuKey = (typeof MENU_DEFS)[number]["key"];

const TitleScreenComponent: React.FC = () => {
  const ctx = useExtensionContext();

  const showGallery = ctx.settings.get<boolean>("showGallery") ?? true;

  const menuItems = MENU_DEFS.filter(
    (d) => d.key !== "gallery" || showGallery,
  ).map((d) => {
    const v = (ctx.settings.get<string>(d.settingKey) ?? "").trim();
    return { key: d.key, label: v || d.defaultLabel };
  });

  const [leaving, setLeaving] = useState(false);
  const [hoverKey, setHoverKey] = useState<MenuKey | null>(null);

  const triggerLeave = (after: () => void) => {
    setLeaving(true);
    window.setTimeout(after, tokens.durBase);
  };

  const onItem = (key: MenuKey) => {
    if (key === "start") {
      triggerLeave(() => ctx.ui.hide("title-screen"));
    } else if (key === "load") {
      // 2026-05 Internal Extension Points:用 slot id 触发,内部走 systemBindings 解析。
      // 2026-05-19: 透传 mode payload,SaveScreen 据此渲染 load-only 按钮组。
      void ctx.system.invoke(INTERNAL_SYSTEM_SLOT.Load, { mode: "load", source: "title" });
    } else if (key === "gallery") {
      // 走鉴赏槽位解析,用户在 Studio 换绑其他鉴赏 UI(含可视化界面)也会被尊重。
      // 默认绑定仍指向本扩展的 gallery-screen。
      void ctx.system.invoke(INTERNAL_SYSTEM_SLOT.Gallery);
    } else if (key === "settings") {
      void ctx.system.invoke(INTERNAL_SYSTEM_SLOT.Settings);
    } else if (key === "exit") {
      triggerLeave(() => ctx.game.exit());
    }
  };

  const [mounted, setMounted] = useState(false);
  useEffect(() => {
    const raf = requestAnimationFrame(() => setMounted(true));
    return () => cancelAnimationFrame(raf);
  }, []);
  const visible = mounted && !leaving;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        backgroundColor: "transparent",
        color: tokens.textPrimary,
        fontFamily: tokens.fontUI,
        overflow: "hidden",
        opacity: visible ? 1 : 0,
        transition: `opacity ${tokens.durBase}ms ${tokens.easeOut}`,
      }}
    >
      {/* vignette 让任意背景下文字可读 */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: `
            radial-gradient(ellipse 70% 80% at 0% 50%, rgba(0,0,0,0.55) 0%, rgba(0,0,0,0) 55%),
            radial-gradient(ellipse 80% 60% at 100% 100%, rgba(0,0,0,0.50) 0%, rgba(0,0,0,0) 60%),
            linear-gradient(180deg, rgba(0,0,0,0.18) 0%, rgba(0,0,0,0) 22%, rgba(0,0,0,0) 78%, rgba(0,0,0,0.22) 100%)
          `,
          pointerEvents: "none",
          opacity: visible ? 1 : 0,
          transition: `opacity ${tokens.durSlow}ms ${tokens.easeOut}`,
        }}
      />

      {/* 顶部细线:从中间向两侧展开 */}
      <div
        style={{
          position: "absolute",
          top: 40,
          left: "50%",
          height: 1,
          background: `linear-gradient(90deg, transparent 0%, ${tokens.borderRegular} 30%, ${tokens.borderRegular} 70%, transparent 100%)`,
          width: visible ? "calc(100% - 96px)" : 0,
          transform: "translateX(-50%)",
          transition: `width ${tokens.durSlow}ms ${tokens.easeOut} 50ms`,
          opacity: 0.6,
        }}
      />

      {/* 右上版本号 */}
      <div
        style={{
          position: "absolute",
          top: 56,
          right: 64,
          fontFamily: tokens.fontMono,
          fontSize: 10,
          letterSpacing: "0.32em",
          textTransform: "uppercase",
          color: tokens.textFaint,
          opacity: visible ? 1 : 0,
          transition: `opacity ${tokens.durSlow}ms ${tokens.easeOut} 140ms`,
        }}
      >
        AVG · ENGINE
      </div>

      {/* 左下小标签 */}
      <div
        style={{
          position: "absolute",
          bottom: 48,
          left: 80,
          fontFamily: tokens.fontMono,
          fontSize: 10,
          letterSpacing: "0.40em",
          textTransform: "uppercase",
          color: tokens.accent,
          opacity: visible ? 1 : 0,
          transform: visible ? "translateY(0)" : "translateY(6px)",
          transition: `all ${tokens.durSlow}ms ${tokens.easeOut} 130ms`,
        }}
      >
        — LetsGal Studio
      </div>

      {/* 右下版权小字 */}
      <div
        style={{
          position: "absolute",
          bottom: 48,
          right: 64,
          fontFamily: tokens.fontMono,
          fontSize: 10,
          letterSpacing: "0.24em",
          textTransform: "uppercase",
          color: tokens.textFaint,
          opacity: visible ? 0.7 : 0,
          transition: `opacity ${tokens.durSlow}ms ${tokens.easeOut} 160ms`,
        }}
      >
        © {new Date().getFullYear()}
      </div>

      {/* —— 主菜单:左侧垂直居中 —— */}
      <nav
        aria-label="主菜单"
        style={{
          position: "absolute",
          left: 96,
          top: "50%",
          transform: "translateY(-50%)",
          display: "flex",
          flexDirection: "column",
          gap: 8,
        }}
      >
        {menuItems.map((item, idx) => (
          <TitleMenuButton
            key={item.key}
            index={idx}
            label={item.label}
            isHover={hoverKey === item.key}
            isOtherHover={hoverKey !== null && hoverKey !== item.key}
            visible={visible}
            onMouseEnter={() => setHoverKey(item.key)}
            onMouseLeave={() => setHoverKey(null)}
            onClick={() => onItem(item.key)}
          />
        ))}
      </nav>

    </div>
  );
};

// ---------- TitleMenuButton ----------

const TitleMenuButton: React.FC<{
  index: number;
  label: string;
  isHover: boolean;
  isOtherHover: boolean;
  visible: boolean;
  onMouseEnter: () => void;
  onMouseLeave: () => void;
  onClick: () => void;
}> = ({
  index,
  label,
  isHover,
  isOtherHover,
  visible,
  onMouseEnter,
  onMouseLeave,
  onClick,
}) => {
  const press = usePressable();

  // 视觉位移:hover +8px / press 回退 -3px(模拟按下回弹)
  const translateX = !visible
    ? -16
    : press.pressed
      ? 4
      : isHover
        ? 10
        : 0;

  return (
    <button
      onMouseEnter={onMouseEnter}
      onMouseLeave={(e) => {
        onMouseLeave();
        press.handlers.onPointerLeave(e as unknown as React.PointerEvent);
      }}
      onPointerDown={press.handlers.onPointerDown}
      onClick={onClick}
      style={{
        position: "relative",
        appearance: "none",
        background: "transparent",
        border: "none",
        color: press.pressed
          ? tokens.accent
          : isHover
            ? tokens.accent
            : tokens.textPrimary,
        fontFamily: tokens.fontDisplay,
        fontSize: "clamp(36px, 4.2vw, 56px)",
        fontWeight: 600,
        lineHeight: 1.15,
        letterSpacing: "0.01em",
        padding: "12px 0 12px 96px",
        textAlign: "left",
        cursor: "default",
        textShadow: "0 2px 24px rgba(0,0,0,0.8)",
        opacity: visible ? (isOtherHover ? 0.4 : 1) : 0,
        transform: `translateX(${translateX}px) scale(${
          press.pressed ? 0.985 : 1
        })`,
        transformOrigin: "left center",
        filter: press.pressed ? "brightness(1.1)" : "brightness(1)",
        transition: `color ${tokens.durFast}ms ${tokens.easeOut}, transform ${tokens.durFast}ms ${tokens.easeOut}, opacity ${tokens.durBase}ms ${tokens.easeOut}, filter ${tokens.durFast}ms ${tokens.easeOut}`,
        animation: visible
          ? `avg-stagger-rise ${tokens.durSlow}ms ${tokens.easeOut} ${
              360 + index * 55
            }ms both`
          : "none",
        whiteSpace: "nowrap",
        userSelect: "none",
      }}
    >
      {/* 数字编号 */}
      <span
        aria-hidden
        style={{
          position: "absolute",
          left: 0,
          top: "50%",
          transform: "translateY(-50%)",
          fontFamily: tokens.fontMono,
          fontSize: 14,
          letterSpacing: "0.18em",
          color: isHover ? tokens.accent : tokens.textFaint,
          fontWeight: 600,
          transition: `color ${tokens.durBase}ms ${tokens.easeOut}`,
          fontVariantNumeric: "tabular-nums",
        }}
      >
        {String(index + 1).padStart(2, "0")}
      </span>

      {/* hover 长指示线 */}
      <span
        aria-hidden
        style={{
          position: "absolute",
          left: 36,
          top: "50%",
          height: 2,
          background: tokens.accent,
          width: isHover ? 52 : 0,
          transform: "translateY(-50%)",
          transition: `width ${tokens.durBase}ms ${tokens.easeOut}`,
          boxShadow: isHover ? `0 0 12px ${tokens.accentGlow}` : "none",
          borderRadius: 999,
        }}
      />

      {label}
    </button>
  );
};

// 统一模块基类形态(2026-06):身份收进 @extension 装饰器,设置用 settings()。
// 本文件同时是 legacy 装饰器语义(tsconfig experimentalDecorators)下
// @extension 双模式实现的真实链路验证。
@extension({
  id: "title-screen",
  label: "标题画面",
  exposeUI: false, // 1.6.0 起只导出 ui/title-screen.json,React 版不再进入 UI 列表
  // 2026-05 Internal Extension Points §6.1:声明本 UI 实现哪些系统槽位。
  supportsSlot: INTERNAL_SYSTEM_SLOT.Title,
})
export class TitleScreen extends Extension {
  // 2026-05 Internal Extension Points:删除 slotUI 字段,改由项目级
  // systemBindings 控制(在 Studio 项目设置 → 系统 面板配置)。
  // 作品名由 build title 决定;背景由先执行的 scene OP 提供;BGM 走 op-play-sound。
  // 这里只暴露四个菜单项的显示文案,留空 = 用默认中文。
  static settings = settings((s: SettingsBuilder) => ({
    startLabel: s.string("「开始游戏」按钮文本").default("开始游戏"),
    loadLabel: s.string("「读取存档」按钮文本").default("读取存档"),
    showGallery: s.boolean("显示「鉴赏」菜单项").default(true),
    galleryLabel: s
      .string("「鉴赏」按钮文本")
      .default("鉴赏")
      .enabledWhen("showGallery"),
    settingsLabel: s.string("「设置」按钮文本").default("设置"),
    exitLabel: s.string("「退出」按钮文本").default("退出"),
  }));

  render() {
    return { component: TitleScreenComponent, props: {} };
  }
}
