import { DEFAULT_DIALOGUE_BOX_V2_CONFIG } from "../../../engine/plugins/custom-slots/slot-v2";

export const FALLBACK_SETTINGS_TEXT_SPEED =
  DEFAULT_DIALOGUE_BOX_V2_CONFIG.behavior.text.char_interval;
const MAX_TEXT_INTERVAL_MS = 200;
const MAX_MENU_TEXT_SPEED = 100;

function clamp(n: number, min: number, max: number): number {
  if (!Number.isFinite(n)) return min;
  return Math.max(min, Math.min(max, n));
}

export function clampTextInterval(charIntervalMs: number): number {
  return clamp(charIntervalMs, 0, MAX_TEXT_INTERVAL_MS);
}

export function getResetTextSpeed(styleDefaultTextSpeed?: number | null): number {
  return clampTextInterval(styleDefaultTextSpeed ?? FALLBACK_SETTINGS_TEXT_SPEED);
}

export function textIntervalToMenuSpeed(charIntervalMs: number): number {
  const safeInterval = clampTextInterval(charIntervalMs);
  return clamp(
    MAX_MENU_TEXT_SPEED -
      (safeInterval / MAX_TEXT_INTERVAL_MS) * MAX_MENU_TEXT_SPEED,
    0,
    MAX_MENU_TEXT_SPEED
  );
}

export function menuSpeedToTextInterval(menuSpeed: number): number {
  const safeSpeed = clamp(menuSpeed, 0, MAX_MENU_TEXT_SPEED);
  return (
    ((MAX_MENU_TEXT_SPEED - safeSpeed) / MAX_MENU_TEXT_SPEED) *
    MAX_TEXT_INTERVAL_MS
  );
}
