// ---------------------------------------------------------------------------
// avg.internal.default-shell —— 默认游戏壳。
//
// 这是 internal 扩展(打 `builtin: true`),跟用户扩展同形态打 bundle,
// 加载机制完全一致(走 ExtensionLoader + SourceProvider 路径)。
// Studio dev 期通过 vite ?raw 把 dist/index.mjs 编进 renderer bundle;
// 玩家壳 build 时把 dist/ 拷到 desktop 产物的 extensions/<id>/ 目录。
//
// 6 个子模块全部用统一模块基类(Extension,2026-06)编写:
//   - @extension({...})         —— 身份(id/label/autonomous/supportsSlot)
//   - static settings(s)        —— 项目设置(settings() 品牌工厂)
//   - static onRegister(ctx)    —— 启动期初始化(模块级,无条件调用)
//   - static method/saveSchema  —— 剧本方法与模块存档
// 范式 —— "一个文件 = 一个模块"。本扩展同时是 legacy 装饰器语义
// (tsconfig experimentalDecorators)下 @extension 双模式实现的真实链路验证。
//
// 加载方:ExtensionLoader 的 collectExtensionExports 通过命名导出收集
// extensionKind === "module" 的 class。1.6.0 起这些 class 只承担控制器、设置、
// 存档和方法职责,统一声明 exposeUI:false；界面只通过下方 visualUI JSON 导出。
// ---------------------------------------------------------------------------

export { manifest } from "./manifest";

// 扩展内可视化界面表(扩展复合容器,2026-07-07):
// ui/*.json 编译期内联进 bundle,运行时经 "ui:@<本扩展id>/<界面名>" 引用。
// internal 扩展没有落地目录,只能走这条编译期通道;文件名即界面名。
const visualUIModules = import.meta.glob("../ui/*.json", { eager: true }) as Record<
  string,
  { default: unknown }
>;
export const visualUI: Record<string, unknown> = Object.fromEntries(
  Object.entries(visualUIModules).map(([path, mod]) => [
    path.replace(/^.*\/([^/]+)\.json$/, "$1"),
    mod.default,
  ]),
);

export { TitleScreen } from "./title-screen";
export { GalleryScreen } from "./gallery-screen";
export { SaveScreen } from "./save-screen";
export { HistoryScreen } from "./history-screen";
export { SettingsScreen } from "./settings-screen";
export { Toolbar } from "./toolbar";
