// ---------------------------------------------------------------------------
// slot-v2 —— 个性化 Schema 重设计 v2 类型层
//
// 本文件只定义新版 Schema 的 TypeScript 类型,不替换 slot.ts 中的运行时类型。
// 引擎和 Studio 后续会逐步迁移到这套类型(分阶段进行,见 progress 文档)。
//
// 设计文档:
//   docs/plans/2026-05-11-personalization-schema-redesign.md
//   docs/plans/2026-05-11-personalization-extension-coexistence.md
//
// 4 层模型:Layout / Appearance / Behavior / Input
// Input 层不在组件 schema 里,统一到 KeyBindingSystem
// ---------------------------------------------------------------------------

import { AVGSlotType } from "./slot";

// ===========================================================================
// 公共类型
// ===========================================================================

/** ["50%", "20px"] 风格的成对单位字符串。沿用旧的 PairUnitStrings 语义。 */
export type PairUnitV2 = [string, string];

/** 9 宫格锚点。布局/位置统一用这个,消除"position 是哪个点"的语义模糊。 */
export type Anchor9 =
  | "top-left"
  | "top-center"
  | "top-right"
  | "center-left"
  | "center"
  | "center-right"
  | "bottom-left"
  | "bottom-center"
  | "bottom-right";

/** 4 边内边距,单位 px。 */
export interface BoxInset {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

/** 缓动函数,跟 CSS easing 直接对应。 */
export type Easing =
  | "ease"
  | "ease-in"
  | "ease-out"
  | "ease-in-out"
  | "linear";

/**
 * 背景定义。
 *
 * 优先级(引擎渲染时):`image > css > 透明`
 *
 * 作者 UI 上不需要 toggle "背景类型",填哪个就用哪个。
 * 彻底取代旧 schema 里 `backgroud_type: "css" | "image"` 字段(typo + 强制二选一)。
 */
export interface Background {
  /** 图片背景。资源 ID 引用,跟资源生命周期管理打通。 */
  image?: {
    asset_id: string;
    size: PairUnitV2;
    position: PairUnitV2;
    repeat: "no-repeat" | "repeat" | "repeat-x" | "repeat-y";
  };
  /** CSS 字符串背景。会被引擎拼成 `background: ${css}`。 */
  css?: string;
}

/**
 * 文字阴影,允许多层叠加(数组)。
 * 跟 CSS `text-shadow` 自然对应:多个阴影逗号分隔。
 */
export interface TextShadow {
  offset_x: number;
  offset_y: number;
  blur: number;
  color: string;
}

/**
 * 文字描边(可选)。
 * 字段化是因为做"轻微描边"在视觉小说很常见,不字段化作者要自己写
 * `-webkit-text-stroke: 1px black; text-stroke: 1px black;` 一组兼容代码。
 */
export interface TextStroke {
  width: number;
  color: string;
}

/**
 * 文字样式 —— 白名单字段,字体走 asset_id。
 *
 * 取代旧 schema 的 `text_styles: Partial<CSSProperties>`。
 * 真要写其他 CSS 装饰,用 `extra_css?` 逃生口。
 */
export interface TextStyle {
  /** 字体资源 ID(跟资源系统打通,引擎做 @font-face 注册)。 */
  font_family_asset_id: string;
  /** 字号,px。 */
  font_size: number;
  font_weight: 100 | 200 | 300 | 400 | 500 | 600 | 700 | 800 | 900;
  font_style: "normal" | "italic";
  color: string;
  /** 行高,倍数(不带单位)。 */
  line_height: number;
  /** 字间距,px。 */
  letter_spacing: number;
  shadows: TextShadow[];
  stroke?: TextStroke;
  /**
   * 水平对齐。V1 的 text_styles.textAlign 在白名单内迁过来,
   * 保留作者通过名字卡 / 对话框配置文本对齐的能力。
   *
   * 注:跟 schema design doc §3 中"text-align 是布局类不该进白名单"的初版
   * 取舍冲突 —— 实践中发现 V1 已有作者用了 textAlign(默认 "left"),
   * 不保留就是破坏性变更。所以白名单收一个,值域限定为 left/center/right。
   */
  text_align?: "left" | "center" | "right";
  /**
   * 文字层逃生口。一段 CSS 声明字符串,会注入到文字元素的 style 上。
   * 详见 §3.1 约定。
   */
  extra_css?: string;
}

// ===========================================================================
// DialogueBox
// ===========================================================================

export interface DialogueBoxLayout_V2 {
  box: {
    size: PairUnitV2;
    position: PairUnitV2;
    /** 默认 "bottom-center"。 */
    anchor: Anchor9;
  };
  /** 文字在框内的内边距。 */
  text_padding: BoxInset;

  name_card: {
    size: PairUnitV2;
    /** 相对 box 的 anchor 锚点的位置。 */
    position: PairUnitV2;
    anchor: Anchor9;
    /** 微调,px。 */
    offset: PairUnitV2;
  };

  wait_cursor: {
    visible: boolean;
    /** 在 box 内的哪个角。 */
    position: Anchor9;
    offset: PairUnitV2;
  };
}

export interface DialogueBoxAppearance_V2 {
  box: {
    background: Background;
    /** 背后遮罩透明度,0-1。 */
    backdrop_opacity: number;
    extra_css?: string;
  };
  /** 对话框正文文字。 */
  text: TextStyle;

  name_card: {
    background: Background;
    text: TextStyle;
    extra_css?: string;
  };

  wait_cursor: {
    /**
     * legacy 保留旧项目的三层 CSS loader；builtin / image 才启用 V2 外观与布局。
     * 旧 V1 配置没有 wait_cursor 对象时，adapter 必须映射成 legacy。
     */
    source: "legacy" | "builtin" | "image";
    icon_asset_id: string;
    /** px。 */
    size: number;
    animation: "rotate" | "blink" | "bounce" | "pulse" | "none";
    /** 单次动画周期，ms。 */
    duration_ms: number;
    /** builtin 图标主色。 */
    primary_color: string;
    /** builtin 图标强调色。 */
    accent_color: string;
  };
}

export interface DialogueBoxBehavior_V2 {
  animation: {
    /** 引用 ShowDialogueBox slot 的 enter 动画。 */
    enter_slot: AVGSlotType.ShowDialogueBox;
    /** 引用 DestroyDialogueBox slot 的 leave 动画。 */
    leave_slot: AVGSlotType.DestroyDialogueBox;
  };
  text: {
    /** ms,逐字间隔(原 text_speed)。 */
    char_interval: number;
    /** ms,每字淡入(原 char_fade_in_duration)。 */
    char_fade_in: number;
  };
  wait_cursor: {
    /** ms,文字结束后多久才显示光标。 */
    delay_after_text: number;
  };
}

/**
 * DialogueBox V2 完整 schema。
 *
 * 跟旧 `AVGSlotData_Dialogue` 的关键差异:
 *  - `key_binding` 整体删除,迁到 KeyBindingSystem(在 device-input-system 内)
 *  - `backgroud_type` 字段删除,改用 `Background.image > css > 透明` 优先级
 *  - `text_styles: Partial<CSSProperties>` 改为白名单 `TextStyle` + `extra_css?`
 *  - 字段加 `anchor`,解决"position 是哪个点"语义模糊
 *  - 4 层模型:layout / appearance / behavior(input 在 KeyBindingSystem)
 */
export interface AVGSlotData_Dialogue_V2 {
  layout: DialogueBoxLayout_V2;
  appearance: DialogueBoxAppearance_V2;
  behavior: DialogueBoxBehavior_V2;
}

// ===========================================================================
// Choice
// ===========================================================================

/** Choice 状态机 4 态。优先级:disabled > active > highlight > default。 */
export interface ChoiceStateStyle {
  text: TextStyle;
  background: Background;
  extra_css?: string;
}

export interface ChoiceLayout_V2 {
  container: {
    size: PairUnitV2;
    position: PairUnitV2;
    anchor: Anchor9;
  };
  arrangement: {
    /**
     * 选项是否居中分布。
     * 注:不支持 horizontal,只竖排;真要横排用扩展。
     */
    centering: boolean;
  };
  item: {
    size: PairUnitV2;
    /** 选项间距,支持 px 数字或百分比字符串(`"10%"`)。 */
    spacing: number | `${number}%`;
  };
  /** 选项内文字内边距。 */
  text_padding: BoxInset;
}

export interface ChoiceAppearance_V2 {
  states: {
    default: ChoiceStateStyle;
    /** 鼠标 hover + 键盘 focus 共用。 */
    highlight: ChoiceStateStyle;
    /** 鼠标按下瞬间。 */
    active: ChoiceStateStyle;
    /** 完全不可点(引擎/扩展运行时触发)。 */
    disabled: ChoiceStateStyle;
  };
}

export interface ChoiceBehavior_V2 {
  animation: {
    enter_slot: AVGSlotType.ShowChoice;
    leave_slot: AVGSlotType.DestroyChoice;
    stagger: {
      mode: "none" | "top-to-bottom" | "fade-in-all";
      /** ms,top-to-bottom 模式下每项延迟(其他模式忽略)。 */
      interval: number;
    };
    state_transition: {
      /** ms,状态间过渡时长(default ↔ highlight ↔ active 等)。 */
      duration: number;
      easing: Easing;
    };
  };
}

/**
 * Choice V2 完整 schema。
 *
 * 跟旧 `AVGSlotData_Choice` 的关键差异:
 *  - 状态机化:default / highlight / active / disabled,文字也有状态分支
 *  - typo 修复:`chioce_*` → 状态结构;`backgroud_type` 删除
 *  - 容器装饰删除(作者要装饰框写扩展)
 *  - border 删除(作者用 background.css 凑合)
 *  - 加 stagger 三种模式(none / top-to-bottom / fade-in-all)
 *  - 没有 visited 状态(走过的查 history-system,扩展自己加 className)
 */
export interface AVGSlotData_Choice_V2 {
  layout: ChoiceLayout_V2;
  appearance: ChoiceAppearance_V2;
  behavior: ChoiceBehavior_V2;
}

// ===========================================================================
// InputBox
// ===========================================================================

/** InputBox 子组件的状态样式(跟 ChoiceStateStyle 同形)。 */
export interface InputBoxItemStyle {
  text: TextStyle;
  background: Background;
  extra_css?: string;
}

export interface InputBoxLayout_V2 {
  container: {
    size: PairUnitV2;
    position: PairUnitV2;
    anchor: Anchor9;
  };
  // 子组件内部布局写死:标题 → 描述 → 输入框 → 按钮,作者不可调
}

export interface InputBoxAppearance_V2 {
  /** 标题:静态,无状态。文案由 Op 传入,不在 schema 里。 */
  title: {
    text: TextStyle;
    background: Background;
    extra_css?: string;
  };
  /** 描述:静态,无状态。文案由 Op 传入。 */
  description: {
    text: TextStyle;
    background: Background;
    extra_css?: string;
  };
  /** 输入框:3 态(default / focused / disabled)。靠 focus 不靠 hover。 */
  input: {
    states: {
      default: InputBoxItemStyle;
      /** 玩家光标在里面。 */
      focused: InputBoxItemStyle;
      disabled: InputBoxItemStyle;
    };
    /** 占位符样式(文案由 Op 传入)。 */
    placeholder: TextStyle;
    caret_color: string;
  };
  /** 按钮:跟 Choice 同款 4 态。 */
  button: {
    states: {
      default: InputBoxItemStyle;
      highlight: InputBoxItemStyle;
      active: InputBoxItemStyle;
      disabled: InputBoxItemStyle;
    };
  };
}

export interface InputBoxBehavior_V2 {
  animation: {
    enter_slot: AVGSlotType.ShowInputBox;
    leave_slot: AVGSlotType.DestroyInputBox;
    state_transition: {
      duration: number;
      easing: Easing;
    };
  };
}

/**
 * InputBox V2 完整 schema。
 *
 * 跟旧 `AVGSlotData_InputBox` 的关键差异:
 *  - 内容文本全部砍掉(`title_text` / `description_text` / `button_text` /
 *    `input_placeholder`),改由 Op 在调用时传入
 *  - 子组件布局写死,作者只能调外层 container
 *  - 输入框状态机:default / focused / disabled
 *  - 按钮状态机:跟 Choice 一致
 *  - 删除两处 `backgroud_type`(`backgroud_type` + `button_background_type`)
 */
export interface AVGSlotData_InputBox_V2 {
  layout: InputBoxLayout_V2;
  appearance: InputBoxAppearance_V2;
  behavior: InputBoxBehavior_V2;
}

// ===========================================================================
// 默认值(配合 v1 默认值标定,语义对齐)
// ===========================================================================
//
// 这些默认值跟 slot.defaults.ts 里的 v1 DEFAULT_*_CONFIG 在视觉上保持一致 ——
// 即 v1↔v2 双向转换之后,引擎渲染出来的画面应该一模一样。
//
// 用作两个场景:
//  1. v1ToV2 / v2ToV1 适配器在字段缺失时的兜底
//  2. Phase 2 之后,作为引擎读取的真正 source of truth
//
// 数值标定原则:
//  - 跟 slot.defaults.ts 的 v1 默认值视觉等价
//  - 老 schema 里没有的概念(anchor / 状态机等)按主设计文档规范填默认
//  - extra_css / 字体 asset_id 等可选字段空字符串/省略

// ─── DialogueBox V2 默认值 ──────────────────────────────────────────────

/**
 * DialogueBox V2 默认配置。视觉上等价于 slot.defaults.ts 的 DEFAULT_DIALOGUE_BOX_CONFIG。
 *
 * 标定来源:
 *  - text_speed: 80 → behavior.text.char_interval: 80
 *  - char_fade_in_duration: 100 → behavior.text.char_fade_in: 100
 *  - styles.dialogue.box_size: "(100%,200)" → layout.box.size: ["100%", "200px"]
 *  - styles.dialogue.box_position: "(center, bottom-200)" → layout.box.position
 *    + anchor: "bottom-center"
 *  - styles.dialogue.text_styles.fontSize: 28 → appearance.text.font_size: 28
 *  - styles.dialogue.text_styles.color: "rgb(231,231,231)" → appearance.text.color
 *  - styles.dialogue.text_styles.textShadow: "1px 1px 4px #131313" → 转 shadows[0]
 *  - styles.dialogue.text_styles.marginTop/Left/Right: 20/200/200 → layout.text_padding
 *  - styles.dialogue.background.css: 渐变 → appearance.box.background.css
 *  - styles.name_card.* 同款映射
 */
export const DEFAULT_DIALOGUE_BOX_V2_CONFIG: AVGSlotData_Dialogue_V2 = {
  layout: {
    box: {
      size: ["100%", "200px"],
      // v1 是 "(center, bottom-200)" — anchor=bottom-center 时 position 表示底边中心
      position: ["50%", "100%"],
      anchor: "bottom-center"
    },
    // bottom = 0 跟 V1 default 视觉等价:V1 text_styles 没定义 marginBottom,
    // React 渲染等价 0px。修复 reviewer C3。
    text_padding: { top: 20, right: 200, bottom: 0, left: 200 },
    name_card: {
      size: ["20%", "40px"],
      // 几何等价于 V1 默认 box_position "(200, bottom-240)":
      //   V1 屏幕坐标:(200px, screenHeight - 240px)
      //   V2 坐标解释:相对 box 的 top-left 锚点(box anchor=bottom-center
      //               + position=(50%, 100%) + size=(100%, 200px))
      //               即 box.top = screenHeight - 200px, box.left = 0
      //               position=(0%, 0%) + offset=(200px, -40px)
      //               → 屏幕位置 = (0 + 200px, screenHeight - 200px - 40px)
      //                          = (200px, screenHeight - 240px) ✓
      // 见 slot-v2-regression.test.ts "I1: name_card 几何等价" 测试组验证。
      position: ["0%", "0%"],
      anchor: "top-left",
      offset: ["200px", "-40px"]
    },
    wait_cursor: {
      visible: true,
      position: "bottom-right",
      offset: ["-20px", "-20px"]
    }
  },
  appearance: {
    box: {
      background: {
        css: "background: linear-gradient(to top, rgba(0,0,0,0.5) 0%, rgba(0,0,0,0) 100%);"
      },
      backdrop_opacity: 0
    },
    text: {
      font_family_asset_id: "",
      font_size: 28,
      font_weight: 400,
      font_style: "normal",
      color: "rgb(231, 231, 231)",
      line_height: 1.5,
      letter_spacing: 0,
      shadows: [{ offset_x: 1, offset_y: 1, blur: 4, color: "#131313" }]
    },
    name_card: {
      background: {},
      text: {
        font_family_asset_id: "",
        font_size: 34,
        font_weight: 400,
        font_style: "normal",
        color: "rgb(255, 247, 7)",
        line_height: 1.5,
        letter_spacing: 0,
        shadows: [{ offset_x: 1, offset_y: 1, blur: 4, color: "#131313" }],
        // V1 默认 name_card.text_styles.textAlign = "left",修复 reviewer I6
        text_align: "left"
      }
    },
    wait_cursor: {
      source: "legacy",
      icon_asset_id: "",
      size: 28,
      animation: "rotate",
      duration_ms: 1000,
      primary_color: "#ffffff",
      accent_color: "#ff3d00"
    }
  },
  behavior: {
    animation: {
      enter_slot: AVGSlotType.ShowDialogueBox,
      leave_slot: AVGSlotType.DestroyDialogueBox
    },
    text: {
      char_interval: 80,
      char_fade_in: 100
    },
    wait_cursor: {
      delay_after_text: 0
    }
  }
};

