import { useCallback, useEffect, useRef, useState } from "react";

/**
 * 给可点击元素提供 press 反馈状态。
 *
 * 用法:
 *   const press = usePressable();
 *   <button {...press.handlers} style={{
 *     transform: press.pressed ? "scale(0.96)" : "scale(1)",
 *     ...
 *   }} />
 *
 * 设计要点:
 *   - pointerdown / pointerup / pointercancel / pointerleave 都重置 pressed
 *     —— 防止"按下后拖出按钮再放开"卡在 pressed 状态
 *   - 全局监听 pointerup,确保即使在按钮外松开也会重置
 *   - press 状态切换有最短显示时长(80ms),太快的点击也能看到反馈
 */
export function usePressable() {
  const [pressed, setPressed] = useState(false);
  const pressedAtRef = useRef<number>(0);
  const releaseTimerRef = useRef<number | null>(null);

  const release = useCallback(() => {
    if (releaseTimerRef.current !== null) return;
    const elapsed = Date.now() - pressedAtRef.current;
    const minVisible = 80;
    if (elapsed >= minVisible) {
      setPressed(false);
    } else {
      releaseTimerRef.current = window.setTimeout(() => {
        releaseTimerRef.current = null;
        setPressed(false);
      }, minVisible - elapsed);
    }
  }, []);

  const onPointerDown = useCallback(() => {
    if (releaseTimerRef.current !== null) {
      window.clearTimeout(releaseTimerRef.current);
      releaseTimerRef.current = null;
    }
    pressedAtRef.current = Date.now();
    setPressed(true);
  }, []);

  // 全局兜底:在按钮外松开也重置
  useEffect(() => {
    if (!pressed) return;
    const onUp = () => release();
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
    return () => {
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
  }, [pressed, release]);

  return {
    pressed,
    handlers: {
      onPointerDown,
      onPointerLeave: release,
    },
  };
}
